INSERT INTO entidade(id, nome, tipo, categoria_id, grupo, partido, campo, cargo, descricao, dossie, uf, nascimento, origem, origem_ref, ind_legado, criado_em, atualizado_em) VALUES('usina-cansancao-de-sinimbu','Usina Cansanção de Sinimbu','empresa','usi',NULL,NULL,NULL,'Usina (AL), em recuperação judicial','A 11ª Turma do TRF-1, com Newton Ramos, acolheu recurso da usina em jan/2024 e rejeitou os da União em jun/2024. O Estadão diz que o Master ingressou como interessado em 21/03/2023; Newton diz que foi depois do julgamento.',NULL,NULL,NULL,'teia','N[188]',188,'2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
