INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(217,'pedro-gonet-branco','daniel-vorcaro','pessoal',NULL,'Convite a fórum em Londres (2025)','Ciro Soares perguntou a Vorcaro, em 29/03/2025, se o filho de Gonet poderia ir ao II Fórum Jurídico Londres; Vorcaro respondeu ''Pedro e ciro ok'' (11/04/2025) e confirmou em 19/06/2025, ''autorizando'' o custeio segundo a PF. O evento de 2025 foi cancelado; não há valor nem confirmação de pagamento. O SBT diz que a PF não achou o contato de Gonet no celular de Vorcaro.','investigacao',NULL,'2025','2025',0,NULL,NULL,NULL,'Gonet: nunca pediu para convidar ou pagar a viagem; só encontrou Vorcaro uma vez em Londres (abril/2024) e teve uma ligação breve em março/2025. A reportagem aponta contradição entre ''sem ligações'' e a ligação descrita.',1,'teia','E[192].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(218,'paulo-gonet','ciro-soares','investigacao',NULL,'Intermediação de contato (PF)','Segundo a PF, Ciro Soares intermediou contatos de Vorcaro com Gonet. A PF relata ainda atuação de Gonet em abril/2024 em favor de Jarbas Soares Júnior, irmão de Ciro, na eleição do CNPG, com base em mensagens/áudio de Ciro (A Crítica). O Conselho Superior do MPF arquivou por 5 a 4 o pedido de investigação criminal contra Gonet (25/09/2026).','investigacao',NULL,'2024','2026',0,NULL,NULL,NULL,'Gonet: único encontro em Londres e uma ligação breve passada por Ciro.',1,'teia','E[193].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
