INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(235,'ibaneis-advocacia','ibaneis-rocha','societaria',NULL,'Escritório ligado à família','A imprensa descreve o escritório como ''de Ibaneis'' ou ligado à família do governador.','reportada',NULL,NULL,NULL,0,NULL,NULL,NULL,'Ibaneis: desligado da sociedade desde o fim de 2018.',1,'teia','E[210].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
