INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(256,'ciro-soares','otto-alencar','politica',NULL,'Contatos sobre o FGC','Mensagens mostram Vorcaro chamando Otto de ''conselheiro'' e ''comandante'' (2024-2025).','investigacao',NULL,'2024','2025',0,NULL,NULL,NULL,'Otto negou contatos e depois admitiu falar ''duas ou três vezes por telefone'', pelo aparelho de Ciro, sobre o FGC (R$ 250 mil para R$ 1 mi), dizendo que se opôs à proposta.',1,'teia','E[231].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(257,'daniel-vorcaro','otto-alencar','politica',NULL,'''Conselheiro'' e ''comandante''','Mensagens de 2024-2025 mostram Vorcaro tratando o senador como ''conselheiro'' e ''comandante'' (Times Brasil).','investigacao',NULL,'2024','2025',0,NULL,NULL,NULL,'Otto: negou e depois admitiu ligações breves sobre o FGC; diz que se opôs à proposta.',1,'teia','E[232].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(258,'walfrido-warde','daniel-vorcaro','juridica',NULL,'Advogado de defesa; ''Estamos infernizando o cara'' (17/11/2025)','A PF diz que Warde tentou contato com o juiz Ricardo Leite (10ª Vara Federal) horas antes da prisão e escreveu a Vorcaro ''Estamos infernizando o cara''; diz ainda que Vorcaro soube da operação por ''meios ilícitos'', por servidores do BC ou por contato de Warde. Warde deixou a defesa em 21/01/2026 (motivo não esclarecido).','investigacao',NULL,'2025','2026',0,NULL,NULL,NULL,'O escritório diz que agiu ''absolutamente dentro da lei'', que quatro escritórios prepararam petição conjunta e que a acusação de obter dados sigilosos é ''caluniosa''.',1,'teia','E[233].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(259,'walfrido-warde','warde-advogados','societaria',NULL,'Fundador','Warde é fundador do escritório. A caracterização política dele na Revista Oeste é de colunista (opinião).','reportada',NULL,NULL,NULL,0,NULL,NULL,NULL,'Sem resposta específica.',1,'teia','E[234].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(260,'walfrido-warde','guido-mantega','politica',NULL,'Articulação junto a Lula (jul/2025)','Estadão/Times Brasil (07/10/2026): em jul/2025 Vorcaro e Warde articularam que Mantega levasse a Lula a versão do Master (17/07 Vorcaro: ''Avise presidente amanhã e vamos pra guerra''; 23/07 Warde: ''Vou pavimentar''). Em áudios (Band, 08/10/2026), Warde cita Moraes e a participação do escritório em ''contratos de consultoria de grande valor''.','investigacao',NULL,'2025','2025',0,NULL,NULL,NULL,'Planalto: Lula se reuniu com Vorcaro uma vez (04/12/2024) e nega presentes ou recados. Hugo Motta: contatos são atividade parlamentar. Alcolumbre e Moraes não se manifestaram.',1,'teia','E[235].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(261,'walfrido-warde','luiz-inacio-lula-da-silva','politica',NULL,'Relato de reunião e uísque (jan/2025)','Registros de jan/2025 (O Globo): Warde relata reunião com Lula e agradecimento por uísque; em 31/07/2025 tentava contato com o chefe de gabinete de Lula.','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'Lula: ''se me deu, já bebi'' (Poder360). A defesa de Flávio Bolsonaro pediu a Mendonça inquérito sobre o uísque.',1,'teia','E[236].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(262,'warde-advogados','banco-master','contratual',NULL,'R$ 76,6 mi (2022-2025)','A Receita enviada à CPI do Crime Organizado lista R$ 76,6 mi a escritórios ligados a Warde (os ''escritórios'' plurais não foram nominados); defesa de Vorcaro e atuação regulatória.','documentada',NULL,'2022','2025',0,NULL,76600000.0,NULL,'O escritório invoca sigilo profissional e diz ter atuado dentro da lei.',1,'teia','E[237].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(263,'monteiro-rusu-cameirao-e-bercht-advogados','banco-master','contratual',NULL,'R$ 79,1 mi (2022-2025), mais R$ 30 mi à Mytra','Receita (via CPI): R$ 79,1 mi ao grupo de escritórios e R$ 30 mi à Mytra Consultoria (R$ 7 mi na declaração de 2024 e R$ 22 mi na de 2025), de Barueri, com o mesmo telefone e e-mail. Serviço: direito creditório e cessões de carteiras, com sala na sede do banco (Metrópoles).','documentada',NULL,'2022','2025',0,NULL,79100000.0,NULL,'O escritório contesta valores, diz que o banco ficou inadimplente, que atuou em cerca de 28 mil processos e reduziu mais de R$ 305 mi em passivos. A defesa de Monteiro diz que as notas fiscais são de serviço lícito.',1,'teia','E[238].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(264,'monteiro-rusu-cameirao-e-bercht-advogados','tirreno','juridica',NULL,'Atuação nas carteiras Tirreno/BRB (~R$ 12 bi)','Segundo o relatório da PF e decisões do STF, o escritório atuou nas carteiras Tirreno/BRB, em cessões de crédito e na estrutura de imóveis atribuídos a Paulo Henrique Costa.','investigacao',NULL,'2023','2025',0,NULL,NULL,NULL,'A defesa diz que a atuação foi estritamente técnica.',1,'teia','E[239].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(265,'daniel-lopes-monteiro','monteiro-rusu-cameirao-e-bercht-advogados','societaria',NULL,'Sócio; saída em fev-mar/2026','Monteiro saiu da sociedade (distrato com efeito em 28/02, segundo a defesa; acordo de 31/03/2026, segundo André Kruschewsky; ''dois dias antes da prisão'', segundo o bnews).','reportada',NULL,NULL,'2026',0,NULL,NULL,NULL,'A defesa de Monteiro não detalha a saída.',1,'teia','E[240].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(266,'daniel-lopes-monteiro','daniel-vorcaro','investigacao',NULL,'''Operador técnico e estrutural'' (preso em 16/04/2026)','Mendonça o chamou de ''operador técnico e estrutural''; a PF, de agente-chave da vertente jurídica e ''compliance paralelo''. Preso na 4ª fase da Compliance Zero; a 2ª Turma manteve a prisão por 3 a 1 (Gilmar vencido, propunha cautelares). A PGR cita proveito próprio de ao menos R$ 86,1 mi.','investigacao',NULL,'2024','2026',0,NULL,86100000.0,NULL,'A defesa ''repudia veementemente'' a tese de operador financeiro e diz que o uso indevido por cliente não se atribui ao advogado.',1,'teia','E[241].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(267,'daniel-lopes-monteiro','paulo-henrique-costa','financeira',NULL,'Arquitetura jurídica de seis imóveis (R$ 146,5 mi)','A PF diz que Monteiro montou a ''arquitetura jurídica'' para ocultar seis imóveis (R$ 146,5 mi) destinados ao ex-presidente do BRB, em empresas em nome de terceiros (incluindo o cunhado Hamilton Suaki); seis empresas ''de prateleira'' tinham o mesmo endereço do escritório.','investigacao',NULL,'2024','2026',0,NULL,146500000.0,NULL,'A defesa alega que é preciso provar participação direta e consciente.',1,'teia','E[242].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
