INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(270,'gabino-kruschewsky-advogados-associados','banco-master','contratual',NULL,'R$ 54 mi (2022-2025)','Folha (via Bahia Notícias): 4º maior pagamento; contencioso de massa do Credcesta. A PF quer apurar se os R$ 54 mi ficaram só no escritório; colunas ligam o caso à Bahia e a mensagem sobre ''8 paus'' (suspeita da PF, coluna). A coluna de Leandro Mazzini o chama de ''segundo mais caro''. Sem operação ou mandado contra o escritório.','documentada',NULL,'2022','2025',0,NULL,54000000.0,NULL,'O escritório diz que atuou em 45 mil processos, valores ''compatíveis com o mercado'', atuação em 19 UFs (7 mil no TJ-BA).',1,'teia','E[245].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(271,'eugenio-kruschewsky','gabino-kruschewsky-advogados-associados','societaria',NULL,'Sócio e líder; procurador do Estado da Bahia','Folha/Bahia Notícias e a coluna de Mazzini nomeiam Eugênio como sócio e líder; a pessoa ''Gabino Kruschewsky'' não é identificada nas fontes.','reportada',NULL,'2022',NULL,0,NULL,NULL,NULL,'Resposta do escritório sobre valores e processos.',1,'teia','E[246].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(272,'eugenio-kruschewsky','andre-kruschewsky','pessoal',NULL,'Primos','Eugênio é primo de André, ex-diretor jurídico do Master, que fez a contratação do escritório.','reportada',NULL,'2022','2024',0,NULL,NULL,NULL,'Não há resposta de André sobre este ponto nas fontes lidas.',1,'teia','E[247].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
