INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(274,'alves-correa-verissimo-advocacia','banco-master','contratual',NULL,'R$ 33 mi em 2024','Auditoria interna do BRB achada pela PF registra R$ 33 mi em 2024; a PF não fez diligência nem avaliou os serviços.','documentada',NULL,'2024','2024',0,NULL,33000000.0,NULL,'O escritório diz que atuou em 1ª e 2ª instância para empresas que venderam créditos ao Master e nunca no STF.',1,'teia','E[249].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
