INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(290,'cnj','usina-capricho','juridica',NULL,'Cancelamento de 16 precatórios (R$ 4,74 bi)','Cautelar assinada em 22/09/2026 (divulgada em 23/09) a pedido da AGU: cancelar 16 precatórios (R$ 4,74 bi) de Capricho, Una e Vale do Ceará Mirim, devolver ao Tesouro, TRF-1 com 5 dias, vedando levantamento, alvará e honorários. Os valores teriam sido depositados em contas judiciais em 12/2023. Segunda cautelar de 28/09: 14 precatórios (R$ 2,36 bi atualizados) de Santa Helena, Agrovale Vale do Curu e Borborema.','documentada',NULL,'2026',NULL,0,NULL,4740000000.0,NULL,'A Una e as demais empresas contestam judicialmente; o CNJ ainda deve analisar as liminares em plenário.',1,'teia','E[265].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
