INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(296,'agu','raizen-energia','juridica',NULL,'União x Raízen (Tema 826)','A AGU sustenta que o dano exige perícia contábil por usina e pode ser zero; as usinas alegam coisa julgada e ''tripla preclusão'' no caso Raízen.','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'Raízen e outras usinas contestam (petição de 09/10/2026).',1,'teia','E[271].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(297,'gilmar-mendes','raizen-energia','juridica',NULL,'Questão de ordem ao plenário (24/09/2026)','Gilmar levou ao plenário a aplicação do Tema 826 a títulos já transitados (União x Raízen), com efeito imediato sujeito a referendo da 2ª Turma; cita R$ 103,4 bi, risco ''provável'' da LDO (1/5 dos R$ 559,1 bi), não o valor de um processo. Votaram com ele Toffoli; Fux pediu vista em 02/10 (relato único do O Brasilianista).','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'As usinas pedem remessa a Fachin (relator prevento) e invocam coisa julgada.',1,'teia','E[272].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
