INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(300,'dias-toffoli','destilaria-alcidia','investigacao',NULL,'Voto decisivo; PF suspeita de interferência (piauí)','A piauí/Poder360 (11/09/2026) relata que a PF suspeita que Vorcaro agiu para mudar a posição de Toffoli na Alcídia, que ele teria votado a favor da União na Raízen (16/09/2024) ''dias antes''; a PF diz que os elementos pedem aprofundamento. O diretor jurídico teria se oferecido para tirar o caso de pauta.','investigacao',NULL,'2024','2026',0,NULL,NULL,NULL,'O gabinete de Toffoli nega alteração de voto e diz que acompanhou o relator na pauta virtual, repetindo o voto no presencial; os dez ministros do STF afirmaram não haver suspeição.',1,'teia','E[275].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(301,'kassio-nunes-marques','destilaria-alcidia','investigacao',NULL,'Voto pelo pagamento; impedimento alegado e revertido','Nunes Marques votou pelo pagamento. A denúncia de Alessandro Vieira (24/09/2026) afirma que o sistema registrou impedimento em fev/2024, revertido em mar/2024 por ''equívoco da assessoria''; a data do julgamento (01/10/2024 ou 03/06/2025), o placar (empate 2x2 desempatado por ele ou 3x2) e o pedido de vista divergem entre fontes.','alegacao',NULL,'2024','2025',0,NULL,NULL,NULL,'Nunes Marques diz que nunca votou em favor de Vorcaro ou do Master e que o julgamento era sobre tese ampla.',1,'teia','E[276].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
