INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(303,'andre-kruschewsky','destilaria-alcidia','investigacao',NULL,'Mensagens: ''Serve de paradigma''; ''Ganhamos Alcídia''','Mensagens atribuídas ao diretor jurídico do Master: ''É importante! Serve de paradigma para nossos casos'', ''Ganhamos Alcídia'' e ''Se precisar de ajuda para tirar de pauta, avisa!'' (piauí/Poder360; denúncia de Vieira). Segundo a denúncia, teria passado o contato de Kevin Marques. A identidade e o cargo à data da mensagem divergem entre fontes.','alegacao',NULL,'2024','2025',0,NULL,NULL,NULL,'Sem resposta de André nas fontes lidas.',1,'teia','E[278].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
