INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(322,'banco-master','metropoles-marketing-e-propaganda','financeira',NULL,'R$ 27,3 mi (2024-2025), com débito imediato a empresas da família Estevão','Coaf (comunicação da Caixa), via JB (09/04/2026): R$ 27.283.800 do Master em 2024-2025, repassados de imediato a Madison, Sense e Macondo, ligadas à família de Luiz Estevão; o Coaf trata como possível movimentação em benefício de terceiros. Mensagem de 01/10/2025 da tesouraria do Master a Vorcaro (''Pagamos metropoles e barci'') consta de relatório da PF. O número vem do Coaf, não da Receita; o texto do JB tem inconsistência de datas.','documentada',NULL,'2024','2025',0,NULL,27283800.0,NULL,'Estevão: patrocínio do Will Bank, transmissão da Série D 2025 e naming rights; diz que o valor devido era maior e ficou parcialmente em aberto, e que o dinheiro recebido ''passa a ser dele''. Nenhuma fonte afirma direcionamento editorial.',1,'teia','E[297].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
