INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(324,'banco-master','grupo-massa-ratinho','financeira',NULL,'R$ 24 mi (2022-2025)','Receita via CPI (Folha, Poder360): Massa Intermediação cerca de R$ 21 mi e Gralha Azul cerca de R$ 3 mi (todos em 2022). A Terra Brasil diz que a reportagem não afirma que sejam publicidade; Poder360 escreve ''pai de Ratinho Junior'' para a Massa.','documentada',NULL,'2022','2025',0,NULL,24000000.0,NULL,'Ratinho Junior (governador do PR) não é sócio das empresas, segundo o grupo.',1,'teia','E[299].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(325,'credcesta','grupo-massa-ratinho','contratual',NULL,'Campanha com Ratinho (R$ 1,68 mi)','Metrópoles via BPMoney (03/09/2026): R$ 1,68 mi em 4 parcelas de R$ 420 mil pela campanha do cartão Credcesta; atrasos em jul/2025 e depois distrato. São contratos distintos dos R$ 24 mi, sem reconciliação nas fontes.','reportada',NULL,'2024','2025',0,NULL,1680000.0,NULL,'A assessoria de Ratinho diz que o banco ''operava regularmente'' ao assinar e que o rompimento veio de atrasos.',1,'teia','E[300].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(326,'banco-master','grupo-globo','contratual',NULL,'Summit Brasil-EUA (Nova York, 15/05/2024) e Domingão','Poder360 (11/03/2026): o Master ''apresentou'' o summit do Valor; Vorcaro abriu o evento. O Will Bank patrocinou o Domingão. O papel é ''apresentou'' (Poder360), ''principal patrocinador'' (Brasil de Fato, opinião) ou ''patrocinador'' (Oeste). O Diário do Comércio traz manchete de R$ 160 mi em patrocínio, não verificada.','reportada',NULL,'2024','2024',0,NULL,NULL,NULL,'A Globo diz que o patrocínio ''segue o mercado'' e que o seminário não serviu a encontros reservados. Poder360: os diálogos não mostram relação ilegal.',1,'teia','E[301].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(327,'luciano-huck','daniel-vorcaro','contratual',NULL,'Mensagens (R$ 83 mi e R$ 26 mi)','Em mensagem de 28/10/2025 Huck cita R$ 83 mi do banco e R$ 26 mi de ''contrato pessoal'' (Veja; Poder360); primeiro contato registrado em nov/2023 e conversas sobre o Will Bank em abr/2024.','reportada',NULL,'2023','2025',0,NULL,83000000.0,NULL,'Huck: houve contrato, notas e impostos, ''não houve sociedade'', e os contratos de imagem foram rescindidos antes da intervenção no Will Bank.',1,'teia','E[302].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
