INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(329,'will-financeira','luciano-huck','contratual',NULL,'Garoto-propaganda e Domingão (dez/2024)','Contrato Will Bank/Domingão em dez/2024; Huck iniciou conversas sobre o Will Bank em abr/2024.','reportada',NULL,'2024','2025',0,NULL,NULL,NULL,'Huck: contratos rescindidos antes da intervenção.',1,'teia','E[304].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(330,'will-financeira','metropoles-marketing-e-propaganda','contratual',NULL,'Patrocínio da Série D','Estevão cita patrocínio do Will Bank e transmissão da Série D (CBF anunciou em 2-3/jul/2025; placa do Will Bank desde 26/07). Os pagamentos de 2025 antecedem esses marcos, segundo o texto do JB.','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'Estevão: patrocínio declarado.',1,'teia','E[305].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(331,'banco-master','leo-dias-comunicacao-e-jornalismo','financeira',NULL,'R$ 9,9 mi do Master (+ R$ 2 mi da LD Produções)','Coaf via Estadão/Broadcast (abr/2026): 6 pagamentos entre fev/2024 e mai/2025 (28% do faturamento do período) e R$ 2 mi em 2 pagamentos (nov/2024 a out/2025) da LD Produções, de Flávio Carneiro (cerca de 90% da receita dela vinha do Master); total cerca de R$ 11,9 mi. Thiago Miranda diz que o Master pagava R$ 1,2 mi/mês por ''mídia'' (não bate com R$ 9,9 mi em 16 meses).','documentada',NULL,'2024','2025',0,NULL,9900000.0,NULL,'Léo Dias: contrato publicitário com o Will Bank (out/2024 a out/2025); nega aporte de Vorcaro ou Zettel; a nota não trata dos R$ 2 mi da LD. Miranda diz que o portal não publicou conteúdo favorável.',1,'teia','E[306].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(332,'thiago-miranda','leo-dias-comunicacao-e-jornalismo','societaria',NULL,'Ex-sócio (saiu em 07/07/2026)','Miranda recebeu 10% da empresa de Léo Dias em out/2025 e diz que Vorcaro teria oferecido R$ 3,5 mi pelo portal (depoimento dele); a venda de 17% a Flávio Carneiro por R$ 10 mi em 19/07/2024 é versão de Miranda. Carneiro nega que Vorcaro fosse sócio.','alegacao',NULL,'2024','2026',0,NULL,NULL,NULL,'Flávio Carneiro nega que Vorcaro fosse sócio da Foone ou do Brazil Journal.',1,'teia','E[307].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(333,'daniel-vorcaro','thiago-miranda','investigacao',NULL,'Projeto DV e investigação de jornalistas','A PF e a decisão de Mendonça apontam ofertas de até R$ 2 mi a influenciadores, investigação de jornalistas (Malu Gaspar, Consuelo Dieguez, Renato Breia/Breita, Milton Maluhy) e gerenciamento de imagem; busca e apreensão em 09/07/2026 (10ª fase) e passaporte apreendido.','investigacao',NULL,'2025','2026',0,NULL,2000000.0,NULL,'A defesa nega ilegalidade e cita presunção de inocência; ele depois entregou contratos e prints a Malu Gaspar.',1,'teia','E[308].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(334,'thiago-miranda','influenciadores-abordados','financeira',NULL,'Ofertas de até R$ 2 mi (dez/2025)','Propostas de R$ 2 mi (3 meses, 8 posts/mês, perfil de mais de 1 mi de seguidores) e R$ 250 mil; pagamento de R$ 7.840 por uma postagem em 19/12/2025 de conta de Miranda a influenciador não identificado (g1, IPJ 82854/2026). O contrato do Projeto DV foi firmado por André Salvador (UNLTD). Números do inquérito: 46 perfis (Gazeta), ao menos 40 (CNN) ou 22 no relatório de fontes abertas.','investigacao',NULL,'2025','2026',0,NULL,2000000.0,NULL,'Rony Gabriel, Juliana Moreira Leite e Leonardo Siqueira recusaram. Defesa de Vorcaro nega o uso de influenciadores.',1,'teia','E[309].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(335,'daniel-vorcaro','influenciadores-abordados','investigacao',NULL,'Campanha contra o BC (inquérito de 28/01/2026)','A PF diz que mensagens do celular indicam orientações a intermediários que trabalham com influenciadores e quer apurar se os perfis foram acionados ''a mando'' de Vorcaro; pico de menções atípico (Febraban) entre 26 e 29/12/2025.','investigacao',NULL,'2025','2026',0,NULL,NULL,NULL,'A defesa de Vorcaro, em petição ao STF, nega o uso de influenciadores.',1,'teia','E[310].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(336,'luiz-bacci','banco-master','investigacao',NULL,'Vídeos defendendo o Master e criticando o BC','Estadão (análise de conteúdo) e Febraban: quatro vídeos (18/12, 29/12, 01/01, 05/01), nenhum marcado como publicidade; está na lista de 22 perfis da Informação 97765/2026 da PF ''sem pagamento documentado''. Nenhuma fonte afirma pagamento.','reportada',NULL,'2025','2026',0,NULL,NULL,NULL,'Procurado, não respondeu (DGABC/Estadão).',1,'teia','E[311].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(337,'malu-gaspar','daniel-vorcaro','investigacao',NULL,'Investigação de sua vida e proposta de contratação','PF (mensagens de mar-abr/2025; Fatos Online em 01/07/2026): Vorcaro e Miranda investigaram sua vida e cogitaram contratá-la; uma ''Carta Proposta'' apreendida previa levá-la ao Leo Dias TV por R$ 120 mil/mês e bônus de R$ 1,5 mi (valores de proposta). Não há texto que diga que foi aceita.','investigacao',NULL,'2025','2026',0,NULL,NULL,NULL,'O Globo repudiou a ''devassa''; sem manifestação da jornalista nos textos.',1,'teia','E[312].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(338,'luiz-phillipi-mourao','diario-do-centro-do-mundo','financeira',NULL,'Intermediou proposta de R$ 50 mil/mês','A PF, em representação ao STF (Jovem Pan, Oeste): mensagens de jul/2024 a set/2025; em set/2024 Vorcaro diz que ''tínhamos comprado os caras''; a PF ''sugere'' intenção de influenciar a linha editorial; recebimento não confirmado.','investigacao',NULL,'2024','2025',0,NULL,NULL,NULL,'O DCM nega receber recursos, diz não saber a que ''DCM'' a decisão se refere e que foi dos que mais publicaram contra o Master; não há investigação contra jornalistas do DCM (advogado).',1,'teia','E[313].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(339,'daniel-vorcaro','diario-do-centro-do-mundo','financeira',NULL,'Proposta de ''parceria'' (out/2024)','Proposta de R$ 50 mil/mês ao site e ''mais 2 editores'' e pedido de pagamentos para ''manter'' a equipe (set/2025), segundo a PF.','investigacao',NULL,'2024','2025',0,NULL,NULL,NULL,'O DCM nega receber recursos.',1,'teia','E[314].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(340,'luiz-phillipi-mourao','a-turma','investigacao',NULL,'Apontado como coordenador','PF e Mendonça descrevem ''A Turma'' como milícia privada de Vorcaro e Zettel, com Sicário coordenando, R$ 1 mi/mês pela King Empreendimentos e R$ 75 mil para cada ''menino''; mensagens sobre Lauro Jardim (''quebrar todos os dentes. Num assalto'') constam da decisão de 04/03/2026. A data da prisão (04/02 ou 04/03/2026) e o relato de morte na cela divergem entre fontes.','investigacao',NULL,'2024','2026',0,NULL,NULL,NULL,'A defesa de Vorcaro diz que as mensagens estão fora de contexto.',1,'teia','E[315].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(341,'daniel-vorcaro','diego-escosteguy','financeira',NULL,'Pagamentos e ''segundo pagamento'' (set/2025)','Mensagens da PF citadas por Malu Gaspar: planilha com R$ 2 mi em seu nome (sem data), pedido de ''segundo pagamento'' em 19/09/2025 e dados bancários da Dez Comunicação em 14/11/2025. A LatAm Journalism Review diz que a PF não investiga o vínculo do veículo com o banqueiro; a apuração sobre vazamento de decisão é separada.','reportada',NULL,'2025','2025',0,NULL,2000000.0,NULL,'Escosteguy: patrocínio e publicidade, prática comum, sem efeito na linha editorial; Vorcaro era fonte. O Oeste observa que o texto não prova ligação entre pagamento e matéria.',1,'teia','E[316].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(342,'entre-investimentos-e-participacoes','istoe','societaria',NULL,'Alegação de participação de Vorcaro','Thiago Miranda (alegação, via Malu Gaspar/Poder360, 18/05/2026) diz que Vorcaro tinha participação na IstoÉ via Entre; coluna de opinião (Jornal Opção) cita ''indícios de conluio fraudulento'' reconhecidos pela Justiça do Trabalho entre Entre e Master, em ação do sindicato por salários atrasados.','alegacao',NULL,'2025','2026',0,NULL,NULL,NULL,'O Grupo Entre diz não atuar como conglomerado de mídia e nega cessão de controle, mas reconhece o uso da Entre no filme.',1,'teia','E[317].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(343,'daniel-vorcaro','grupo-voto','financeira',NULL,'Custeio da palestra de Tony Blair (Londres, abr/2024)','Poder360/Gazeta: Vorcaro custeou a palestra de Blair (cachê estimado em ~£ 120 mil) e a degustação de uísque Macallan de 25/04 (~US$ 641 mil); programa de Londres de cerca de US$ 6 mi (R$ 30 mi) segundo documentos à CPMI do INSS. A Gazeta diz não confirmar quem pagou a degustação. Mensagem de 26/04/2024: Vorcaro ditou a um contato ''Geraldo Brazil Journal'' texto sobre encontro de Moraes, Toffoli e Gilmar com Blair (veículo e pessoa não confirmados).','reportada',NULL,'2024','2024',0,NULL,NULL,NULL,'O Grupo Voto diz que os patrocinadores são sigilosos por contrato e confirma só a palestra de Blair; o Master chamou de ''estratégia de marca''. Sem resposta dos ministros sobre o texto.',1,'teia','E[318].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
