INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-1995-efeito-tequila-apos-a-crise-do-peso','Efeito Tequila após a crise do peso mexicano','Após a desvalorização do peso em dezembro de 1994, os EUA e organismos internacionais montaram no início de 1995 um pacote de socorro de cerca de US$ 50 bilhões e a crise contagiou outros emergentes, incluindo o Brasil, no episódio conhecido como efeito Tequila.','1995',0,NULL,'documentada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[1995].intl.eventos[0]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-1995-emendas-que-flexibilizam-monopolios','Emendas que flexibilizam monopólios estatais','Ao longo de 1995 o Congresso promulga emendas constitucionais (EC 5 a 9) que flexibilizam monopólios estatais em gás canalizado, telecomunicações e petróleo e extinguem a distinção entre empresa nacional e estrangeira.','1995',0,NULL,'documentada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[1995].pol.eventos[1]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-1995-fed-passa-a-cortar-juros','Fed passa a cortar juros','O Fed cortou a meta dos fed funds para 5,75% em julho e para 5,50% em 19 de dezembro de 1995, depois de tê-la elevado a 6,00% em fevereiro.','1995',0,NULL,'documentada',2,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[1995].intl.eventos[3]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
