INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2021-condenacoes-de-lula-anuladas-moro','Condenações de Lula anuladas; Moro considerado parcial','Em 8/3/2021 o ministro Edson Fachin, do STF, anula as condenações de Lula na Lava Jato por incompetência da Justiça de Curitiba, e em 23/3 a Segunda Turma do STF decide por 3 votos a 2 que o ex-juiz Sergio Moro foi parcial no caso do tríplex.','2021',0,NULL,'reportada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2021].pol.eventos[2]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
