INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2021-cpi-da-covid-instalacao-e-relatorio','CPI da Covid: instalação e relatório final','Instalada no Senado em 27/4/2021, a CPI da Pandemia aprova em 26/10, por 7 votos a 4, o relatório do senador Renan Calheiros (MDB-AL), que pede 80 indiciamentos, entre eles o do presidente Jair Bolsonaro por nove crimes, e é entregue em 27/10 à PGR e ao STF para as providências cabíveis.','2021',0,NULL,'reportada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2021].pol.eventos[3]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2021-fed-anuncia-o-inicio-da-reducao-das','Fed anuncia o início da redução das compras de ativos','Em 3 de novembro de 2021 o Fed anunciou cortes mensais de US$ 10 bilhões nas compras de Treasuries e de US$ 5 bilhões nas de títulos hipotecários, mantendo a meta dos fed funds em 0%–0,25%.','2021',0,NULL,'documentada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2021].intl.eventos[1]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
