INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2022-pec-da-transicao-vira-a-emenda','PEC da Transição vira a Emenda Constitucional 126','Aprovada no Senado em 7/12/2022 (64 a 16 e 64 a 13, relator Alexandre Silveira) e na Câmara em 21/12 (331 a 163 no 2º turno, relator Elmar Nascimento), que reduziu a vigência de dois anos para um, a PEC é promulgada no mesmo dia e libera R$ 145 bilhões fora do teto de gastos em 2023.','2022',0,NULL,'documentada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2022].pol.eventos[5]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
