INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-brics-convida-seis-paises-a-aderir','Brics convida seis países a aderir','Na cúpula de Joanesburgo, em agosto de 2023, o Brics convidou Argentina, Egito, Etiópia, Irã, Arábia Saudita e Emirados Árabes a entrar a partir de 1º de janeiro de 2024; a Argentina retirou o pedido em 29 de dezembro.','2023',0,NULL,'reportada',3,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].intl.eventos[3]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-congresso-promulga-a-reforma-tributaria','Congresso promulga a reforma tributária (EC 132)','Em 20/12/2023 o Congresso promulga a Emenda Constitucional 132, que cria o IBS e a CBS para substituir cinco tributos sobre o consumo; a Câmara aprovou a PEC 45 em 7/7 (382 a 118 e 375 a 113), o Senado, com relatoria de Eduardo Braga, em 8/11 (53 a 24) e a Câmara concluiu a votação em 15/12.','2023',0,NULL,'documentada',5,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].pol.eventos[5]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-cpmi-do-8-de-janeiro-instalacao-e','CPMI do 8 de Janeiro: instalação e relatório final','Instalada em 25/5/2023, com presidência do deputado Arthur Maia (União-BA) e relatoria da senadora Eliziane Gama (PSD-MA), a CPMI aprova em 18/10, por 20 votos a 11, o relatório que pede o indiciamento de 61 pessoas, entre elas Jair Bolsonaro.','2023',0,NULL,'documentada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].pol.eventos[1]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-fed-leva-os-juros-a-5-25-5-50','Fed leva os juros a 5,25%–5,50%','Em 26 de julho de 2023 o Fed elevou a meta dos fed funds para a faixa de 5,25% a 5,50%, por unanimidade dos onze votantes.','2023',0,NULL,'documentada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].intl.eventos[1]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-lei-complementar-200-cria-o-novo','Lei Complementar 200 cria o novo arcabouço fiscal','Em 30/8/2023 é sancionada a Lei Complementar 200, que substitui o teto de gastos por metas de resultado primário e limites de despesa que crescem a 70% (ou 50%, se a meta não for cumprida) da variação da receita; a Câmara aprovou o texto-base em 23/5 por 372 a 108, com relatoria de Claudio Cajado.','2023',0,NULL,'documentada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].pol.eventos[3]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-milei-e-eleito-e-o-peso-argentino-e','Milei é eleito e o peso argentino é desvalorizado em 54%','Em 19 de novembro de 2023 Javier Milei venceu o segundo turno com 55,65% dos votos e em 12 de dezembro o governo anunciou a desvalorização do câmbio oficial, de 366,5 para cerca de 800 pesos por dólar (54%), em vigor no dia seguinte.','2023',0,NULL,'reportada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].intl.eventos[2]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-quebra-do-svb-e-venda-do-credit-suisse','Quebra do SVB e venda do Credit Suisse ao UBS','Em 10 de março de 2023 o Silicon Valley Bank, com US$ 209 bilhões em ativos, quebrou e em 19 de março o UBS anunciou a compra do Credit Suisse por 3 bilhões de francos suíços, em operação articulada pelo governo suíço.','2023',0,NULL,'reportada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].intl.eventos[0]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-stf-e-congresso-divergem-sobre-o-marco','STF e Congresso divergem sobre o marco temporal','Em 21/9/2023 o STF decide por 9 votos a 2 que a tese do marco temporal é inconstitucional; em 27/9 o Senado aprova o PL 2.903, sancionado em 20/10 como Lei 14.701 com vetos, que o Congresso derruba em 14/12 (Câmara 321 a 137, Senado 53 a 19).','2023',0,NULL,'reportada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].pol.eventos[4]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-tse-torna-bolsonaro-inelegivel-por-oito','TSE torna Bolsonaro inelegível por oito anos','Em 30/6/2023 o TSE decide por 5 votos a 2 declarar Jair Bolsonaro inelegível por oito anos a partir da eleição de 2022, por abuso de poder político e uso indevido dos meios de comunicação em reunião com embaixadores em 18/7/2022, em ação movida pelo PDT.','2023',0,NULL,'documentada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].pol.eventos[2]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-01-22-11a-turma-do-trf-1-acolhe-recurso-da','11ª Turma do TRF-1 acolhe recurso da Cansanção de Sinimbu','Sessão virtual unânime de 22-26/01/2024; Newton Ramos integrava a turma. Ele diz que o relator era outro e que o agravo foi julgado em bloco (cerca de 300 processos).','2024-01-22',0,NULL,'reportada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[13]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
