INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-04-11-gilmar-recebe-vorcaro-e-advogados-do','Gilmar recebe Vorcaro e advogados do Master no STF','Reunião às 18h, intermediada por Chiquinho Feitosa, ex-cunhado do ministro, ''às vésperas'' do julgamento da Alcídia (CNN). Gilmar diz que foi institucional e que votou contra o Master em todos os casos do setor. Revelada pela Folha em 17/09/2026.','2024-04-11',0,NULL,'reportada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[15]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
