INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-congresso-aprova-a-regulamentacao-da','Congresso aprova a regulamentação da reforma tributária','A Câmara conclui em 10/7/2024 a votação do PLP 68/2024, que regulamenta a EC 132; o Senado o aprova em 12/12 por 49 a 19 (relator Eduardo Braga) e em 17/12 a Câmara, com relatoria de Reginaldo Lopes, rejeita parte das mudanças e envia o texto à sanção, concluída em 16/1/2025 (LC 214).','2024',0,NULL,'documentada',4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2024].pol.eventos[0]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-cupula-do-g20-no-rio-lanca-alianca','Cúpula do G20 no Rio lança Aliança contra a Fome','Em 18 e 19/11/2024 o Rio sediou a cúpula do G20; a declaração dos líderes lançou a Aliança Global contra a Fome e a Pobreza (148 membros fundadores, 82 países) e incluiu compromisso de tributar os super-ricos.','2024',0,NULL,'documentada',4,'brasil',NULL,NULL,NULL,'manual','Y[2024].intl.eventos[5]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
