INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2025-10-10-inss-nao-renova-acordo-consignado-do','INSS não renova acordo consignado do Master','O INSS suspendeu preventivamente o Master do consignado a aposentados por volume expressivo de reclamações e indícios de descumprimento de regras de autorização e biometria; o acordo vigorou de 2020 a set/2025.','2025-10-10',0,NULL,'reportada',4,'teia',NULL,NULL,NULL,'teia','teia:EV[86]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2025-10-14-gaeco-aponta-executivos-da-reag-e-fundo','Gaeco aponta executivos da Reag e fundo Mabruk II na Usina Itajobi','Segundo reportagem do Estadão, o Gaeco suspeita que a Reag e a Altinvest ajudaram a estruturar fundos usados na compra da Usina Itajobi, com recursos de Mourad. A Reag diz que seus diretores atuaram como representantes legais dos fundos.','2025-10-14',0,NULL,'investigacao',4,'teia',NULL,NULL,NULL,'teia','teia:EV[87]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
