INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2025-11-17-bc-comunica-ao-mpf-indicios-de-fraude','BC comunica ao MPF indícios de fraude entre Master e fundos da Reag','Relatório enviado ao TCU aponta operações com falhas graves entre jul/2023 e jul/2024 envolvendo fundos administrados pela Reag Trust (entre eles Bravo 95 e D Mais), dentro de R$ 11,5 bi em operações estruturadas. A Reag disse não ter visto o relatório e nega elo com o PCC.','2025-11-17',0,NULL,'reportada',5,'teia',NULL,NULL,NULL,'teia','teia:EV[90]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2025-11-17-fictor-anuncia-compra-do-master-vorcaro','Fictor anuncia compra do Master; Vorcaro é preso','A Fictor Holding anunciou a compra do Master com consórcio dos Emirados, aporte de R$ 3 bilhões e troca de nome para Banco Fictor, condicionada a BC e Cade. Na noite do mesmo dia Vorcaro foi detido no aeroporto de Guarulhos ao embarcar para Dubai; a defesa diz que a viagem era comercial.','2025-11-17',0,NULL,'documentada',5,'teia','lado: contexto',NULL,NULL,'teia','teia:EV[88]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
