INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-02-18-bc-liquida-o-banco-pleno-ex-voiter','BC liquida o Banco Pleno (ex-Voiter)','Liquidação por comprometimento da situação econômico-financeira, deterioração da liquidez e descumprimento de determinações do BC. O banco pertencia a Augusto Lima, a quem o Master o vendeu em setembro de 2025. O FGC terá de ressarcir cerca de R$ 4,9 bilhões a cerca de 160 mil credores, segundo o Estadão reproduzido pela Revista Oeste.','2026-02-18',0,NULL,'documentada',4,'teia',NULL,NULL,NULL,'teia','teia:EV[121]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-02-24-cvm-lista-18-procedimentos-sobre-os','CVM lista 18 procedimentos sobre os grupos Master e Reag','São 6 inquéritos administrativos, 8 processos sancionadores com acusação e 4 encerrados por termo de compromisso. Inclui processo de 2021 contra o Banco Master e os Vorcaro e processos contra a Reag por demonstrações financeiras não entregues.','2026-02-24',0,NULL,'documentada',4,'teia',NULL,NULL,NULL,'teia','teia:EV[122]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-03-04-3a-fase-vorcaro-e-preso-de-novo','3ª fase: Vorcaro é preso de novo','Por decisão de Mendonça, Vorcaro e Zettel foram presos; também foi preso o suposto coordenador operacional de ''A Turma'', e buscas atingiram o ex-diretor de Fiscalização do BC Paulo Sérgio Neves de Souza. Mendonça apontou risco à integridade física de pessoas e a PF encontrou mensagens sobre plano contra um jornalista. Em sessão virtual de 13 a 20/03, Mendonça, Fux e Nunes Marques votaram por manter a preventiva na Segunda Turma; Toffoli se declarou suspeito.','2026-03-04',0,NULL,'investigacao',5,'teia',NULL,NULL,NULL,'teia','teia:EV[123]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-03-11-mansur-na-cpi-master-era-cliente-da-reag','Mansur na CPI: Master era cliente da Reag e nega vínculo com PCC','Amparado por decisão do ministro Flávio Dino, ficou calado em boa parte da sessão. Disse que o Master era cliente como outras instituições e que as páginas da Carbono Oculto não mencionam associação com o PCC.','2026-03-11',0,NULL,'alegacao',4,'teia',NULL,NULL,NULL,'teia','teia:EV[127]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
