INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-07-17-brb-encerra-o-memorando-com-a-quadra','BRB encerra o memorando com a Quadra','Em fato relevante de 17/07, o BRB informou que não daria continuidade à venda de ativos do Master objeto do memorando com a Quadra, sem que as diligências necessárias fossem concluídas; o BRB disse que as tratativas foram encerradas de forma consensual, e a Folha relatou divergências em parâmetros econômicos e financeiros. A entrada de R$ 3 a 4 bilhões não se concretizou, e o BRB afirma que fará a gestão e a recolocação dos ativos.','2026-07-17',0,NULL,'reportada',4,'teia',NULL,NULL,NULL,'teia','teia:EV[150]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
