INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(344,76,'sustenta','tinha um contrato com o Banco Master que previa o pagamento de R$ 129 milhões em três anos',0,'Veículo fora da lista nominal; trecho é parcial (sujeito da frase é o escritório de Viviane Barci de Moraes, esposa do ministro).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(345,286,'sustenta','recebeu R$ 281 mil em 10 parcelas da empresa de consultoria contratada pelo Master e pela JBS.',0,'Consult confirmou o pagamento de R$ 281 mil por serviços jurídicos e técnicos; título inferido da URL. A defesa de Kevin não foi localizada.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(346,1331,'sustenta','filho do ministro Luiz Fux',0,'Fala em ''proximidade''; não usa ''contato frequente''. Material ''não confirma por si só qualquer ilegalidade do ministro''. Título inferido da URL; JB pode não estar na lista nominal.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(347,300,'sustenta','o escritório passou a ser representado pelo advogado Enrique de Abreu Lewandowski, filho do ministro',0,NULL,'boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(348,1332,'sustenta','teve como acionistas os irmãos e um primo do ministro Dias Toffoli',0,'Cobre irmãos, Maridt e fundo da Reag/Zettel; não confirmei os nomes José Carlos e José Eugênio nesta página. Data da página incerta (cita nota de 12/2/2026).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(349,1332,'sustenta','teve como acionistas os irmãos e um primo do ministro Dias Toffoli',0,'Confirma ''primo'' e o resort Tayayá, mas não vi o nome Mario Umberto Degani nem ''controlava em 2020'' nesta página.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(350,1298,'sustenta','sua ex-esposa, a advogada Roberta Maria Rangel, viu o número de processos em que atuava no STF e no STJ saltar 140%',0,'Fonte descreve como ex-esposa, não vínculo atual.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(351,308,'sustenta','Gonet perguntou se Vorcaro poderia incluir seu filho, Pedro Gonet, na lista de autoridades',0,'Cita relatório da PF. Rede nacional, mas SBT News pode estar fora da lista nominal. Sem ''Branco'' no sobrenome.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(352,1299,'sustenta','cunhada de Hugo Motta (irmã de Luana Motta, esposa do parlamentar)',0,'Grafo diz ''familiar''; fonte: cunhada.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(353,1299,'sustenta','a ETC Participações, empresa controlada por Bianca Medeiros',0,'Vínculo é indireto (empresa da cunhada), não da família em sentido direto.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(354,313,'sustenta','a BK Financeira, empresa de Bonnie de Bonilha',0,'O trecho cita a empresa; o título e a matéria a descrevem como nora de Wagner. Segundo outra matéria, é casada com Eduardo Sodré, enteado de Wagner.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(355,313,'sustenta','pagou ao menos R$ 11 milhões à empresa da nora',0,'Nome na matéria: BK Financeira (BN Financeira só na de 18/6). Bonnie é casada com Eduardo Sodré, enteado de Wagner. Wagner nega intermediação. Título inferido da URL.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(356,1300,'sustenta','Enteado do líder do governo no Senado, o secretário de Meio Ambiente da Bahia, Eduardo Sodré',0,'Fonte descreve como enteado, não ''familiar'' genérico.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(357,1301,'sustenta','O irmão do senador Ciro Nogueira (PP), Raimundo Neto e Silva Nogueira Lima, é um dos alvos da 5ª fase',0,NULL,'boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(358,1301,'sustenta','administrador formal de CNLF',0,'Confirma CNLF com irmão como administrador formal e compra de ações da Green Investimentos (Felipe Vorcaro) por R$ 1 mi vs R$ 13 mi; NÃO traz ''pertenceria ao senador'' nem ''30%''.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(359,1540,'sustenta','comprou um crédito de R$ 38 milhões do escritório do advogado Caio Carvalho Barros, filho do governador do Distrito Federal, Ibaneis Rocha (MDB)',0,'Original do Estadão (a negociação foi revelada por Malu Gaspar, O Globo; o Estadão teve acesso ao documento). Confirma ''filho'' e o crédito de R$ 38 mi; Ibaneis afastado do escritório desde 2018; Caio sócio desde 2022.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(360,1302,'sustenta','para a produção sobre a vida do pai, o ex-presidente Jair Bolsonaro (PL)',0,'Parentesco é explícito só por ''pai''; a matéria não usa a palavra ''filho''. Eduardo nega ter recebido recursos.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(361,1303,'sustenta','um dos irmãos dele, o agricultor Luis Roberto',0,'Trecho parcial (irmão de Paulo Sérgio).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(362,1333,'sustenta','tentando embarcar para Brasília com R$ 510 mil em espécie na bagagem de mão',0,'Nome ''Valéria Rodrigues Linhares''; Dino autorizou a operação em 5/9. Não vi ''esposa'' explícito no trecho. Título inferido da URL.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(363,362,'sustenta','de propriedade da advogada Camilla Ramos, esposa do desembargador Newton Ramos',0,'Grafo diz ''familiar''; fonte: esposa.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(364,362,'sustenta','escritório Queiroga, Vieira, Queiroz & Ramos',0,'Fonte grafa ''Queiroga, Vieira, Queiroz & Ramos'' (sigla QVQR não aparece). Vínculo via esposa Camilla Ramos, ''esposa do desembargador Newton Ramos'' (TRF-1); honorários ''poderiam chegar a R$ 427 milhões em caso de êxito total''. Veículo regional; reportagem original/primeiro veículo não identificado.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(365,323,'sustenta','O Escritório Ibaneis Advocacia e Consultoria recebeu R$ 73,8 milhões pela venda de honorários de precatórios',0,'Confirma o nome ''Ibaneis Advocacia'' e vendas a fundos da Reag. Não vi aqui a defesa ''afastado desde 2018'' (está no Correio Braziliense). Título inferido da URL.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(366,300,'sustenta','o escritório de advocacia do ex-ministro Ricardo Lewandowski',0,'Reportagem original (Andreza Matais e Andre Shalders). Nome ''a Lewandowski Advocacia'' aparece literalmente; R$ 6,5 milhões brutos, dos quais R$ 5,25 milhões após ir para o MJSP; ele deixou a sociedade em jan/2024 e o escritório é tocado pelos dois filhos.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(367,1536,'sustenta','Chiquinho Feitosa, irmão da advogada Guiomar Feitosa (ex-mulher de Gilmar Mendes)',0,'Linha de apoio: ''Chiquinho Feitosa (ex-cunhado de Gilmar Mendes)''. O vínculo é por ser irmão da ex-mulher do ministro; data exata da matéria não confirmada (set/2026). Não traz R$ 500 mil mensais (isso consta na Rádio Itatiaia, 18/9/2026, sem fonte original).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(368,1288,'sustenta','Foi um dos fundadores do Partido da Social Democracia Brasileira (PSDB).',0,'Matéria sobre os presidentes (FHC 1995–2002) e o PSDB; não é o resultado do TSE (site do TSE inacessível no ambiente).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(369,1291,'sustenta','fundador do Partido dos Trabalhadores',0,'Posse em 1º/1/2003; vitória no 2º turno com 61,27%.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(370,1287,'sustenta','Dilma Vana Rousseff, do Partido dos Trabalhadores',0,NULL,'boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(370,1295,'sustenta','determinou o afastamento de Dilma Rousseff da Presidência da República pelo período de até 180 dias.',1,'Afastamento em 12/5/2016 (fim do exercício conforme descrição); saída definitiva em 31/8/2016.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(371,1296,'sustenta','manter, defender e cumprir a Constituição',0,'Posse definitiva em 31/8/2016; Temer assumiu como interino em 12/5/2016 (fonte Agência Brasil não aberta). Mandato até 31/12/2018. Página cita Temer no PMDB.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(371,1297,'sustenta','Michel Temer tem uma vida dedicada ao PMDB',1,NULL,'boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(372,1328,'sustenta','O presidente Jair Bolsonaro anunciou nesta terça-feira (12) a saída do PSL',0,'Complementa a fonte da Câmara (eleição pelo PSL): confirma saída do PSL em nov/2019.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(373,1292,'sustenta','Filiado ao PT, Lula sucede o presidente Jair Bolsonaro nos próximos quatro anos.',0,'Posse em 1º/1/2023; mandato vai até 2026 (descrição diz 2023 a 2025).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(374,1293,'sustenta','foi exercida por ele nos dois mandatos de Fernando Henrique Cardoso | indicado pelo PFL',0,'Período: a fonte indica vice-presidência de 1995 a 1º/1/2003 (descrição diz 1995 a 2002, aceitável como ano de término do mandato). Partido: PFL.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(375,1329,'sustenta','Filiado ao Partido Republicano Brasileiro (PRB), Alencar pode deixar ainda mais confuso o quadro eleitoral em Minas Gerais.',0,'CONTRADIÇÃO: mandato de vice 2003-2010 correto, mas o partido (PL) só vale até set/2005; depois PMR/PRB.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(375,1330,'sustenta','José Alencar havia saído do PL no auge do escândalo do mensalão.',1,'Filiou-se ao PMR em 29/9/2005, sendo vice-presidente.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(376,1287,'sustenta','Michel Temer, do PMDB, foi empossado como vice-presidente.',1,'Trecho parafraseado a partir da leitura da página (PMDB ligado a Temer; posse em 1º/1/2011).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(376,1297,'sustenta','para assumir como vice de Dilma Rousseff',0,'Vice de 2011 até 2016 (descrição diz 2011 a 2015). Partido PMDB confirmado na mesma página (''uma vida dedicada ao PMDB'').','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(377,1294,'sustenta','O vice-presidente eleito é o general da reserva Hamilton Mourão (PRTB).',0,NULL,'boa');
