INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(679,1222,'sustenta','em nome da Liderança do Governo, registrar o mais vivo júbilo pela indicação do eminente Senador Fernando Bezerra',0,'Prova mais antiga aberta: 15/8/1995 (Suplicy, em aparte: ''como Líder do Governo, V. Exª...''). A data exata da posse na liderança (provavelmente fev-mar/1995) não foi encontrada. Partido PFL pela página oficial ''Senadores da 50ª Legislatura por partido'' e pelo cabeçalho do discurso.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(680,1223,'sustenta','Quando tive oportunidade de ser convidado pelo Presidente Fernando Henrique Cardoso para exercer a Liderança do Governo',0,'Fala de 27/10/1998, em retrospecto. Perfil oficial (perfil/18): mandato 1991-1999, exercício encerrado em 31/12/1998. ACM, em 4/10/1999 (pronunciamento 250939), lembra que perdeu a eleição ao governo do ES ''mesmo como Líder do Governo''. O fim exato da liderança não foi encontrado. 1996 e 1997 ficam sem linha: não há prova própria desses anos.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(681,1193,'sustenta',NULL,0,NULL,NULL);
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(681,1224,'sustenta','Líder do Governo, no Senado Federal, entre 03/08/1999 e 24/05/2001.',1,'Quem liderou o governo no Senado entre jan/1999 (fim do exercício de Élcio Álvares) e 3/8/1999 não foi encontrado. As linhas de 2000 e 2001 já existiam (o mesmo perfil foi ligado a elas em evidencias-rodada6.json). Partido PSDB pelo Relatório da Presidência 2000.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(682,1212,'sustenta',NULL,0,NULL,NULL);
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(682,1225,'sustenta','como Líder do Governo e Senador pelo Estado de Roraima',1,'O início exato (entre 24/5 e 1/8/2001) não foi encontrado. Em 2000 era vice-líder do governo (Relatório da Presidência 2000).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(683,1212,'sustenta',NULL,0,NULL,NULL);
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(683,1226,'sustenta','Fui Líder do Governo Fernando Henrique, nesta Casa, com muita honra durante dois anos',1,'Fala de 18/2/2003, em retrospecto; o fim provável é dez/2002-jan/2003 (não datado). O partido em 2003 não foi verificado.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(684,1173,'sustenta',NULL,0,NULL,NULL);
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(684,1227,'sustenta','para exercer a Liderança do Bloco PSDB/PTB a partir desta data',1,'No índice do mesmo Diário: ''Assunção, pelo orador, do cargo de Líder do PSDB''. A UF não consta no trecho aberto: fica NULL aqui e o confronto com a API da Câmara (mandato-oficial.json, `complementos`) a preenche.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(685,1228,'sustenta','Sinto que é do meu dever, como Líder do Governo, não silenciar neste momento',0,'Discurso de 7/8/1996 sobre o debate das medidas provisórias; o cabeçalho do DSF traz ''Como Líder''. No discurso de 27/6/1996 (pronunciamento 189659, DSF 28/6/1996 p.10905) ele registra a indicação de José Roberto Arruda ''para assumir a Liderança do Governo no Congresso Nacional'' (outra função, não a do Senado).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(686,1229,'sustenta','que faz algumas críticas muito pesadas e fortes em relação à Liderança do Governo',0,'Resposta à revista IstoÉ, 14/10/1997; cabeçalho do DSF: ''Como Líder''. Prova mais fraca que a de 1996 (o discurso fala da Liderança do Governo e ele fala ''Como Líder'', mas a frase ''Líder do Governo'' não foi lida na página); a continuidade em 1996-1998 também vem das linhas de 1995 e 1998 e do perfil oficial de Arruda (''2º Vice-Líder do Governo'' de 20/3/1995 a 31/1/1999).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(687,1230,'sustenta','Deputada Sandra Starling, Líder do PT',0,'Ofício nº 79/96 (079/PT, de 13/2/1996) que indica os vice-líderes do PT. A UF não consta no trecho aberto: fica NULL. Leitura do PDF OCR do Diário feita por ferramenta de extração; conferir o trecho no original.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(688,1231,'sustenta','De acordo, Deputado José Anibal, Líder do PSDB.',0,'Comunicação de filiação do Deputado Nicias Ribeiro. A UF não consta no trecho aberto: fica NULL. Leitura do PDF OCR do Diário feita por ferramenta de extração; conferir o trecho no original.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(689,1232,'sustenta','Deputado Pedrinho Abrão, Líder do PTB',0,'Ofício nº 13/96. A UF não consta no trecho aberto: fica NULL. Leitura do PDF OCR do Diário feita por ferramenta de extração; conferir o trecho no original.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(690,1232,'sustenta','escolheram o Deputado Odelmo Leão, para Líder do Bloco Parlamentar PPB/PL',0,'Na p.04662 do mesmo Diário: ''foi reconduzido ao cargo de Líder da Bancada do nosso Partido''. A UF não consta no trecho aberto: fica NULL. Leitura do PDF OCR do Diário feita por ferramenta de extração; conferir o trecho no original.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(691,1227,'sustenta','Votos de profícua gestão ao novo Líder do partido, Deputado Walter Pinheiro.',0,'No mesmo Diário (p.03347): ''Assunção do orador ao cargo de Líder da bancada do Partido dos Trabalhadores''. Partido e UF (PT-BA) do Sumário do mesmo Diário. A data exata da assunção não consta no que foi lido (Diário de 21/2/2001, sessão de 20/2). Leitura do PDF OCR do Diário feita por ferramenta de extração; conferir o trecho no original.','boa');
