INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1990-extincao-do-iaa-que-fixava-precos-do',494,'sustenta',1,'novacana.com',NULL,NULL,NULL);
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-criacao-da-organizacao-mundial-do',1233,'sustenta',0,'A brief history (WTO Annual Report 2023)','The WTO began life on 1 January 1995, succeeding the General Agreement on Tariffs and Trade (GATT) which had regulated world trade since 1948.','A fonte diz que o GATT ''regulated world trade since 1948'' (não ''em vigor''); essencialmente equivalente.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-criacao-do-proer',1234,'sustenta',0,'Resolução CMN nº 2.208, de 3/11/1995','Programa de Estímulo à Reestruturação e ao Fortalecimento do Sistema Financeiro Nacional (PROER) ... assegurar liquidez e solvência ao referido Sistema','Confirma a resolução do CMN de 3/11/1995.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-criacao-do-proer',1235,'sustenta',1,'Medida Provisória nº 1.179 de 03/11/1995','Dispõe sobre medidas de fortalecimento do Sistema Financeiro Nacional e dá outras providências.','Ementa não cita o Proer; o campo de indexação da página lista ''PROGRAMA DE ESTIMULO A REESTRUTURAÇÃO E AO FORTALECIMENTO AO SISTEMA FINANCEIRO NACIONAL (PROER)''. Confirma a MP de 3/11/1995.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-efeito-tequila-apos-a-crise-do-peso',1470,'sustenta',0,'Press Briefing by Secretary of State Warren Christopher and Secretary of the Treasury Robert Rubin','Put together, the $37 billion of intermediate term money that we now have [...] $20 billion from the Exchange Stabilization Fund [...] the IMF increased its participation to $17.5 billion','Confirma o pacote de socorro dos EUA/FMI ao México em jan/1995 e a queda forte do peso. Nao confirma o total de ~US$ 50 bi (fonte soma US$ 20 bi ESF + FMI 17,5/17,8 bi + outros) nem o contagio ao Brasil. FMI: 17,5 bi na fala vs 17,8 bi no comunicado conjunto.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-efeito-tequila-apos-a-crise-do-peso',1507,'sustenta',1,'Clinton, Facing Fight On Mexican Bailout, Drafts Rescue Plan','will provide Mexico with $20 billion from the Treasury Department''s Emergency Exchange Fund. [...] It will also provide $17.7 billion from the International Monetary Fund, [...] another $10 billion in short-term financing from the Swiss-based Bank of International Settlements.','CONFIRMA em parte: pacote anunciado no inicio de fev/1995 soma 20 + 17,7 + 10 = ~US$ 47,7 bi (aprox. 50 bi; EBSCO fala em US$ 52 bi anunciados em 31/1/1995). Materia nao menciona Brasil nem contagio; o efeito Tequila sobre o Brasil nao foi sustentado por fonte aberta nesta rodada (artigo PUC-Rio de M. Garcia cita ''efeito tequila... contagiaria a Argentina, chegando em seguida ao Brasil'', mas e academico). [trecho via resumo do WebFetch]','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-emendas-que-flexibilizam-monopolios',1236,'sustenta',0,'Emenda Constitucional nº 9, de 9 de novembro de 1995','A União poderá contratar com empresas estatais ou privadas a realização das atividades','EC 9 (petróleo, art. 177). Lida também a EC 8 (telecom, 15/8/1995, https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc08.htm) e a EC 5 (gás canalizado, 15/8/1995, art. 25 §2). EC 6 (15/8/1995) revoga o art. 171, mas a página não descreve a distinção empresa nacional/estrangeira.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-fed-passa-a-cortar-juros',772,'sustenta',0,'Open Market Operations Archive','1995: February 1 (increase 50, 6.00); July 6 (decrease 25, 5.75); December 19 (decrease 25, 5.50)','Citação é reconstrução das linhas da tabela (data, variação em pb, nível). Página não rotula explicitamente a coluna como meta de fed funds.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-greve-dos-petroleiros',1237,'sustenta',0,'Greve histórica dos petroleiros completa 15 anos','ocupou com tanques e metralhadoras as refinarias da Petrobrás ... impôs multas milionárias à FUP e aos sindicatos','Texto da imprensa da FUP publicado pela CUT (perspectiva sindical). Confirma início 3/5, 32 dias, suspensão proposta em 2/6, Exército nas refinarias em 24/5, multas do TST (26/5) e 73 demitidos. A multa é atribuída ao TST (descrição diz Justiça do Trabalho; compatível).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-mercosul-vira-uniao-aduaneira',1304,'sustenta',0,'Mercosul: período de transição (Comissão Parlamentar Conjunta do Mercosul)','passaria a vigorar a partir de 1º de janeiro de 1995, conforme estabelecido pelo Protocolo de Ouro Preto','Mesma comissão da fonte fraca; dá ''janeiro de 1994 a janeiro de 1995'' para entrada em vigor da união aduaneira e Ouro Preto (17/12/1994) com estrutura vigente em 1/1/1995; a TEC só foi concluída no fim de 1994. Compatível com ''janeiro de 1995''. Trecho conforme retornado pela ferramenta de leitura.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-posse-de-fernando-henrique-cardoso',1471,'sustenta',0,'FHC questiona reeleição em documentário que estreia no dia 31','sendo empossado em 1º de janeiro de 1995','Confirma a posse em 1/1/1995. Nao confirma o percentual de 54,3% dos votos validos nem a eleicao no 1o turno (pagina do TSE consultada so exibia tabela do exterior, 55,22%, nao utilizavel).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-posse-de-fernando-henrique-cardoso',1508,'sustenta',1,'Discurso de posse de Fernando Henrique Cardoso no Congresso Nacional','BRASÍLIA, DF, 1O DE JANEIRO DE 1995','CONFIRMA a data da posse (1/1/1995) por dateline do discurso de posse; hospedado na Fundacao FHC (institucional, texto primario). Percentual: pagina oficial do TSE (resultados 1994) abriu apenas a tabela do EXTERIOR, onde FHC tem 55,22% (14.744 votos) - isso explica o 55,22% citado antes da Biblioteca do TSE: e base exterior, nao nacional. 54,3% nacional NAO verificado por fonte oficial. [trecho via resumo do WebFetch]','boa');
