INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1997-privatizacao-da-vale-do-rio-doce',1509,'sustenta',10,'25 anos da privatização da Vale','num leilão realizado em 6 de maio de 1997 [...] O negócio envolveu, na época, cerca de R$ 3,3 bilhões.','CONFIRMA data (leilao em 6/5/1997) e valor (~R$ 3,3 bi) explicitamente. Nao nomeia CSN/Consorcio Brasil (''grupo de empresas privadas e fundos de pensao''); veiculo de vies critico - sem fonte neutra aberta encontrada. [trecho via resumo do WebFetch]','boa');
