INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1997-queda-em-hong-kong-e-em-wall-street',794,'contexto',0,NULL,NULL,NULL,NULL);
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1997-queda-em-hong-kong-e-em-wall-street',795,'contexto',1,NULL,NULL,NULL,NULL);
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1997-queda-em-hong-kong-e-em-wall-street',1474,'sustenta',2,'Crash in share values feared after dramatic decline on Wall Street','the Dow Jones index fell by over 554 points, a drop of 7.18 per cent','Confirma Dow -554 pontos (7,18%) na segunda-feira 27/10/1997. Esta materia cita queda de ''mais de 6%'' do Hang Seng; a queda de dois digitos (13,7%) esta em reportagem da NPR de 28/10/1997 (npr.org/1997/10/28/1037556/winners-losers-in-h-k: ''the 13.7 percent drop in the value of the Hong Kong stock market''), nao nesta.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1997-queda-em-hong-kong-e-em-wall-street',1510,'sustenta',3,'Markets wrap 27/10/1997','the Dow tumbled 554.26 points, or 7.18 percent, to 7,161.15 [...] after Hong Kong''s benchmark Hang Seng index lost almost 6 percent overnight','CONFIRMA Dow -554 pts (7,18%) em 27/10/1997. CONTRADIÇÃO parcial: em 27/10 o Hang Seng caiu ~6% (nao dois digitos); a queda de dois digitos em um dia (-14%) e de 28/10 (ver NPR); queda de 23% entre 20 e 23/10 nao confirmada. [trecho via resumo do WebFetch]','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1997-queda-em-hong-kong-e-em-wall-street',1511,'sustenta',4,'Hong Kong market drop','The Hang Seng Index plunged 14%, the worst drop since markets crashed in October 1987.','CONFIRMA queda de dois digitos (-14%) em um unico dia no Hang Seng no fim de outubro/1997; a pagina nao traz data de pregao explicita (veiculada 23/10/1997). [trecho via resumo do WebFetch]','boa');
