INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1998-russia-desvaloriza-o-rublo-e-declara',1478,'sustenta',5,'Russia Economy','the Russian government has agreed to devalue the ruble [...] The Kremlin also announced a 90-day moratorium on repayment of foreign debt.','Confirma desvalorizacao do rublo e moratoria de 90 dias em 17/8/1998 (data pela URL/arquivo da NPR). Nao confirma o pacote FMI/Banco Mundial; ver evidencia complementar da RFE/RL.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1998-russia-desvaloriza-o-rublo-e-declara',1479,'sustenta',6,'Russia: IMF Approves First Loan Package','the center-piece of a financial rescue package that will total around $22.6 billion by the end of next year.','Confirma o pacote total de ~US$ 22,6 bi. Dateline 21/7/1998 (a pagina tambem exibe 9/7/1998, inconsistencia); a descricao diz aprovacao em 20/7. A materia trata o emprestimo do Banco Mundial (US$ 1,7 bi) separadamente.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1998-russia-desvaloriza-o-rublo-e-declara',1513,'sustenta',7,'Press Release 98/31: IMF Approves Augmentation of Russia Extended Arrangement and Credit under CCFF','July 20, 1998 [...] has approved financial support totaling SDR 8.5 billion (about US$11.2 billion) for the Russian Federation.','CONFIRMA aprovacao do FMI em 20/7/1998 (resolve a duvida 13/7 vs 20/7: 20/7). CONTRADIÇÃO parcial: o FMI informa SDR 8,5 bi (~US$ 11,2 bi) do proprio Fundo; os US$ 22,6 bi (FMI + Banco Mundial + Japao) nao aparecem neste comunicado. [trecho via resumo do WebFetch]','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1998-russia-desvaloriza-o-rublo-e-declara',1514,'sustenta',8,'News Brief 98/30: Camdessus Comments on Russian Actions','a change in exchange rate policy, restructuring of government debt [...] a temporary restriction on capital payments abroad','CONFIRMA que em 17/8/1998 o governo russo anunciou medidas (mudanca cambial, reestruturacao da divida publica, restricao temporaria a pagamentos de capital ao exterior). CONTRADIÇÃO: o texto nao usa ''desvalorizacao'' nem ''moratoria de 90 dias''. [trecho via resumo do WebFetch]','boa');
