INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1999-cpis-do-judiciario-e-do-sistema',1484,'sustenta',12,'Pronunciamentos do Senador Eduardo Suplicy - abril de 1999','AVALIAÇÃO POSITIVA DO INICIO DOS TRABALHOS DA CPI DO SISTEMA FINANCEIRO.','Resumo oficial de discurso de 14/04/1999: confirma que a CPI do sistema financeiro ja iniciava trabalhos nessa data (compativel com criacao em 14/4). Nao confirma a CPI do Judiciario em 8/4.','boa');
