INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1999-segundo-mandato-de-fhc',1471,'sustenta',11,'FHC questiona reeleição em documentário que estreia no dia 31','Tomou posse em 1º de janeiro de 1999.','Confirma o inicio do segundo mandato em 1/1/1999.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1999-segundo-mandato-de-fhc',1538,'sustenta',12,'Na posse, FHC diz não ser "gerente de crise"','O presidente Fernando Henrique Cardoso, 67, assumiu ontem o seu segundo mandato com um discurso morno','Edição de 2/1/1999: ''ontem'' = 1/1/1999; posse no plenário da Câmara. Confirma a data; a Biblioteca da Presidência estava ''em manutenção'' e o Planalto exige login.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-argentina-em-recessao',1305,'sustenta',0,'Brazil Trade Summary 2000 (WITS)','Argentina ... con una proporción de 11.33 % de los asociados','Confirma Argentina em 2º lugar (11,33%) entre destinos das exportações brasileiras em 2000, atrás dos EUA (24,29%). O PIB (-0,79%) segue na URL do Banco Mundial original, que já era dado oficial.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-cassacao-do-senador-luiz-estevao',1238,'sustenta',0,'Por 56 votos a 19, Senado cassa Demóstenes Torres','pela primeira vez na sua história, cassou um senador ... em sessão fechada, houve 52 votos pela cassação do senador do Distrito Federal','Confirma ano 2000, 52 votos a favor, 18 contra, 10 abstenções e pioneirismo; não traz o dia 28/6. Congresso em Foco (outra matéria) cita ''junho de 2000'' via Correio Braziliense. Gazeta do Povo (conselho de ética) data erroneamente em 2001. Substituição parcial: a nova fonte confirma o ano e o pioneirismo, mas não traz mês/dia nem o placar 52x18x10; esta continua ligada para essas partes (https://www.congressoemfoco.com.br/noticia/48086/ex-senador-cassado-luiz-estevao-responde-a-131-processos-na-justica-do-df).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-cassacao-do-senador-luiz-estevao',1306,'sustenta',1,'Ex-senador cassado Luiz Estevão responde a 131 processos na Justiça do DF','Em 2000, Luiz Estevao tornou-se o primeiro senador a ser cassado pelo plenário','Confirma 2000 e pioneirismo, sobre o próprio Luiz Estêvão (a fonte fraca era sobre Demóstenes). Não traz mês/dia nem o placar 52x18x10.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-eleicoes-municipais',1239,'sustenta',0,'Marta vence Maluf e é eleita prefeita de S.Paulo','A candidata do PT Marta Suplicy foi eleita prefeita de Sao Paulo, obtendo 3.248.115 votos (58,51%).','Confirma 2º turno em 29/10/2000 contra Maluf (PPB). Veículo regional (Diário do Grande ABC), não TSE.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-emenda-constitucional-29-saude',1240,'sustenta',0,'Emenda Constitucional nº 29, de 13 de setembro de 2000','recursos mínimos derivados da aplicação de percentuais calculados sobre','Confirma 13/9/2000; União, estados, DF e municípios aplicam percentuais mínimos de suas receitas em saúde.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-fed-leva-os-juros-a-6-50',772,'sustenta',0,'Open Market Operations Archive','2000: February 2 (increase 25, 5.75); March 21 (increase 25, 6.00); May 16 (increase 50, 6.50)','Citação é reconstrução das linhas da tabela. A última mudança listada em 2000 é 16/5 (6,50%), consistente com manutenção até o fim do ano. Altas: 25+25+50 pb (fev. 2, mar. 21, mai. 16).','boa');
