INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-petroleo-em-alta',1242,'sustenta',0,'Global price of Brent Crude (série FMI, anual)','1999: 18.108; 2000: 28.845 (US$/barril); 1996: 20.81; 1992: 19.36','Série do FMI (via FRED/Fed St. Louis). Confirma 18,11 em 1999 e 28,85 em 2000 e que 2000 é o maior valor entre 1992 e 2000.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-pico-e-inicio-do-estouro-da-bolha-da',1488,'sustenta',0,'Nasdaq surpasses Internet-bubble peak to set new record','The index’s last record close of 5,048.62 was hit on March 10, 2000.','Confirma recorde de 5.048,62 em 10/3/2000. Nao confirma a queda de 78% do Nasdaq-100 ate out/2002.','boa');
