INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-cassacoes-de-roberto-jefferson-e-jose',1243,'sustenta',0,'Dirceu é cassado por diferença de 37 votos','Logo após a meia-noite, o Plenário da Câmara cassou o deputado José Dirceu (PT-SP). ... No dia 14 de setembro, Jefferson perdeu o mandato','A matéria é de 1/12/2005 e diz que a cassação de Dirceu ocorreu logo após a meia-noite (sessão de 30/11 que virou 1/12); o dia 14/9 de Jefferson confere.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-china-encerra-a-paridade-fixa-com-o',1308,'sustenta',0,'Central bank statement on currency changes','Starting from July 21, 2005, China will reform the exchange rate regime ... adjusted to 8.11 yuan per US dollar','Reproduz o comunicado do PBoC: 21/7/2005, 8,11 yuan/US$, referência a cesta de moedas.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-denuncia-do-mensalao',1244,'sustenta',0,'20 anos de Mensalão: entenda como tudo começou','No dia 16 daquele mês, Dirceu pediu demissão da Casa Civil e retomou seu mandato de deputado.','Retrospectiva de 2025 (não da época). Confirma a entrevista de Jefferson à Folha em 6/6/2005 e a saída de Dirceu em 16/6.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-eleicao-e-renuncia-de-severino',1245,'sustenta',0,'Severino renuncia, mas promete voltar à Câmara','Severino Cavalcanti renunciou na tarde desta quarta-feira ao seu mandato de deputado federal.','A renúncia foi ao mandato de deputado (consequentemente à presidência), em 21/9/2005; a página não detalha a propina.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-eleicao-e-renuncia-de-severino',1246,'sustenta',1,'Aldo Rebelo — Portal da Câmara dos Deputados','Foi eleito presidente da Câmara dos Deputados no dia 28 de setembro de 2005, em segundo turno, por 258 votos a 243.','Confirma a eleição de Aldo em 28/9; a vitória de Severino sobre o candidato governista (fevereiro) consta em nsctotal.com.br/noticias/relembre-eleicoes-conturbadas-no-congresso (não incluída como entrada separada).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-fed-sobe-juros-em-todas-as-reunioes-do',840,'sustenta',0,'Open Market Operations - Historical changes of the target federal funds rate','December 13 | 25 | 4.25 ... June 30 | 25 | 1.25 (2004)','Tabela oficial: oito altas de 25 pb em 2005 (2/2 a 13/12, nível 4,25%) e início do ciclo em 30/6/2004 (1,25%). Trecho é linha de tabela.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-katrina-e-petroleo-mais-caro',1247,'sustenta',0,'Surviving the Storm','Katrina damaged or destroyed 30 oil platforms and caused nine refineries to close','Confirma plataformas/refinarias. Preço do Brent: ver próxima entrada.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-katrina-e-petroleo-mais-caro',1248,'sustenta',1,'Table Data - Crude Oil Prices: Brent - Europe','2004: 38.26; 2005: 54.57 (dólares por barril, médias anuais)','CONTRADIÇÃO: a série EIA/FRED dá média de US$ 54,57 (2005) e US$ 38,26 (2004), e não 54,68 e 38,23. A diferença pode vir de outra fonte (ex. BP). Substituição parcial: a nova fonte (série primária de preços) não cobre a parte do Katrina (plataformas e refinarias); esta continua ligada para essa parte (https://www.eia.gov/dnav/pet/hist/LeafHandler.ashx?n=PET&s=RBRTE&f=A).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-katrina-e-petroleo-mais-caro',1309,'sustenta',2,'Europe Brent Spot Price FOB, Annual (EIA)','2004: 38.26; 2005: 54.57 (US$/barril)','Fonte primária da série (a FRED é espelho). NÃO cobre a parte do Katrina (30 plataformas / 9 refinarias): só offshore-technology.com (trade) afirma literalmente; CRS diz 35 plataformas destruídas p/ Katrina+Rita e NBC 9 refinarias paradas.','boa');
