INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2012-julgamento-do-mensalao-no-stf',1399,'sustenta',13,'Dirceu é condenado a quase 11 anos de prisão; Delúbio 8 e Genoino quase 7','Dos 37 réus, 25 foram condenados e 12 absolvidos.','Confirma pena de Dirceu de 10 anos e 10 meses. Fala em 37 réus (e não 38) no julgamento final. As 69 sessões aparecem em congressoemfoco.com.br/noticia/50711.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2012-julgamento-do-mensalao-no-stf',1526,'sustenta',14,'STF começa hoje a julgar os 38 réus do chamado mensalão','dá início hoje, às 14 horas, ao julgamento do chamado mensalão','Confirma início em 2/8/2012 e 38 réus. Não confirma 69 sessões nem pena de Dirceu (10 anos e 10 meses). Complemento institucional: noticias.stf.jus.br confirma que o julgamento da AP 470 começaria em 2/8.','boa');
