INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2012-rio-20-reune-88-chefes-de-estado-e-de',1499,'sustenta',4,'United Nations Conference on Sustainable Development Concludes with World Leaders Renewing Commitments to Save Planet','Early estimates put the total participation at close to 46,000 [...] Overall, over 100 Heads of State and Government addressed the highly anticipated gathering.','CONTRADIÇÃO: a ONU fala em mais de 100 chefes de Estado e de governo (título do evento diz 88) e ~46 mil participantes (descrição: 45,4 mil). Confirma adoção por consenso de ''The Future We Want'' e encerramento em 22/6/2012; não afirma 13/6 como início nesta página.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2012-rio-20-reune-88-chefes-de-estado-e-de',1546,'sustenta',5,'Summary report, 13-22 June 2012','PrepCom III: ''scheduled to take place for three days, from 13-15 June 2012''; ''The UN Conference on Sustainable Development opened on Wednesday, 20 June 2012.''; ''...convened back-to-back in Rio de Janeiro, Brazil, from 13-22 June 2012.''','Sustenta a correção das datas (evento-correcoes.json, rodada 6): 13-22/6 é o intervalo total; a Conferência em si foi de 20 a 22/6, precedida pela 3ª reunião do Comitê Preparatório (13-15/6). Corroboração: un.org/en/conferences/environment/rio2012 (''20-22 June 2012, Rio de Janeiro'').','boa');
