INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2015-colapso-do-preco-das-commodities',1313,'sustenta',0,'IMF Commodity Market Monthly, January 2016','Iron Ore $/MT 135.4 96.8 55.2','CONTRADIÇÃO: neste boletim o Brent é 98.9 (2014) e 52.4 (2015), preliminar; a descrição usa 99,35 e 53,02 (série FRED/FMI revisada). Minério 96.8/55.2 confirmado.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2015-eduardo-cunha-assume-a-camara',1263,'sustenta',0,'Novo presidente da Câmara, Cunha quer independência sem prejuízo à governabilidade','eleito neste domingo (1º) presidente da Câmara dos Deputados para o biênio 2015-2017','Cunha 267 votos, Arlindo Chinaglia (PT-SP) 136 em segundo, primeiro turno. Chinaglia é PT-SP.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2015-fed-inicia-o-ciclo-de-alta-de-juros',840,'sustenta',0,'Open Market Operations - Historical changes of the target federal funds rate','December 17 | 25 | 0 | 0.25-0.50 ... 2008 December 16 ... 0-0.25; 2006 June 29 | 25 | 5.25','Tabela confirma faixa anterior 0-0,25 (desde 16/12/2008) e última alta em 29/6/2006. A tabela data a mudança em 17/12 (vigência); o comunicado FOMC é de 16/12.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2015-manifestacoes-contra-o-governo',1264,'sustenta',0,'Dilma volta a ser pressionada pelas ruas (página em /noticia/44038/brasileiros-voltam-as-ruas-contra-governo-federal)','superou o registrado na manifestação de 12 de abril, estimado em 560 mil manifestantes','Cobre 12/4 (560 mil) e 16/8 (~795 mil, PMs); 15/3 citado com ~2 milhões na estimativa do texto, bem acima de ''centenas de milhares''. Título da página inferido do conteúdo retornado, URL slug diferente.','boa');
