INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-china-cresce-e-compra-um-terco-das',1269,'sustenta',0,'GDP growth (annual %) NY.GDP.MKTP.KD.ZG, 2020','CHN 2.3395; USA -2.0814; WLD -2.8862 (GDP growth, annual %, 2020)','PIB confere (China 2,34; EUA -2,08).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-china-cresce-e-compra-um-terco-das',1270,'sustenta',1,'China contribuiu com mais da metade do superávit comercial do Brasil','A participação do país saiu de 28,1% para 32,3% de 2019 para 2020.','CONTRADIÇÃO: fonte dá 32,3%, não 32,41%. O MDIC/Siscomex (gov.br) não publica o percentual: só US$ 70,08 bi para China+HK+Macau (~33%). Substituição parcial: a nova fonte cobre só 2,34% e -2,08%; os 32,3% só estão na Agência Brasil (esta), que continua ligada para essa parte (https://api.worldbank.org/v2/country/CHN;USA/indicator/NY.GDP.MKTP.KD.ZG?date=2020:2020&format=json).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-china-cresce-e-compra-um-terco-das',1315,'sustenta',2,'World Bank: GDP growth (annual %) - China and United States, 2020','China 2.33950385203023; United States -2.081375977796','Cobre 2,34% e -2,08%. A fonte fraca (Agência Brasil, ''de 28,1% para 32,3%'') já sustenta os 32,3% da descrição e é veículo nacional; pode ser mantida para essa parte.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-fed-zera-os-juros',1271,'sustenta',0,'Federal Reserve issues FOMC statement','the Committee decided to lower the target range for the federal funds rate to 0 to 1/4 percent.','Corte anterior em 3/3 para 1-1 1/4% (https://www.federalreserve.gov/newsevents/pressreleases/monetary20200303a.htm). Manutenção até o fim do ano: comunicado de 16/12/2020 mantém 0 a 1/4% (https://www.federalreserve.gov/newsevents/pressreleases/monetary20201216a.htm). O corte de 3/3 foi de 0,5 p.p., para 1 a 1 1/4%.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-guerra-de-precos-do-petroleo',1272,'sustenta',0,'How negative oil prices revealed the dangers of futures trading','a price war erupted between oil giants Saudi Arabia and Russia in early March','WTI a cerca de -US$ 37 em 20/4 confirmado. Data exata 8/3 não consta na página (''início de março''). Brent média 2020 = 43.33 confirmado em https://fred.stlouisfed.org/data/POILBREUSDA (série do FMI). Obs.: o -37 refere-se ao contrato de maio. Substituição parcial: a nova fonte confirma a guerra de preços e a data de 8/3; esta (CNBC) continua ligada apenas para o WTI a cerca de -US$ 37 em 20/4 (https://www.npr.org/2020/03/08/813439501/saudi-arabia-stuns-world-with-massive-discount-in-oil-sold-to-asia-europe-and-u-).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-guerra-de-precos-do-petroleo',1316,'sustenta',1,'Saudi Arabia stuns world with massive discount in oil sold to Asia, Europe and U.S.','Late last week, Saudi Arabia, the rest of OPEC and Russia failed to agree on production cuts','Reportagem de 8/3/2020 (data inferida do slug/URL); mantém CNBC apenas para o WTI -37 em 20/4.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-novo-fundeb',1317,'sustenta',0,'Senadores comemoram promulgação da emenda que torna o Fundeb permanente','Senadores comemoram promulgação da emenda que torna o Fundeb permanente','Confirma promulgação da EC 108 em 26/8/2020 e que torna o Fundeb permanente; não usa a palavra complementação (fala em subir a parte da União de 10% a 23% até 2026).','boa');
