INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-pandemia-de-covid-19-2',1275,'sustenta',0,'WHO Director-General''s opening remarks at the media briefing on COVID-19 - 11 March 2020','We have therefore made the assessment that COVID-19 can be characterized as a pandemic.','Os dois eventos ''Pandemia de covid-19'' NÃO são o mesmo fato: -2 trata da declaração da OMS e do PIB mundial; o outro, das medidas do Congresso (DL 6, Lei 13.982).','boa');
