INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2024-cupula-do-g20-no-rio-lanca-alianca',1543,'sustenta',0,'G20 Rio de Janeiro Leaders'' Declaration','The leaders of the G20 met in Rio de Janeiro on 18-19 November, 2024, to address major global challenges and crises','Trecho truncado pela ferramenta. Versão em PT (PDF do Poder360, não oficial): ''Nós, os líderes do G20, nos reunimos no Rio de Janeiro de 18 a 19 de novembro de 2024''; a Aliança aparece no parágrafo 15 da versão PT, sem o número de membros.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2024-cupula-do-g20-no-rio-lanca-alianca',1544,'sustenta',1,'Argentina joins Global Alliance against Hunger and Poverty','The G20 Leaders'' Summit in Rio de Janeiro officially launched the Alliance, with 148 founding members. ... brings together 148 founding members, including 82 countries','Divergência menor: o boletim G20 Radio (gov.br/g20, bulletin-151) diz ''81 countries, 26 international organizations'' no corpo e ''82 countries'' no título; Planalto e JB dizem 82 (com a Argentina, que aderiu em 18/11).','boa');
