INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(60,'lacuna','teia',NULL,NULL,'Data de aquisição do Letsbank e do Banco Vipal: não encontrada.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(61,'lacuna','teia',NULL,NULL,'Denúncia formal da PGR contra Vorcaro ou ação penal recebida pelo STF: não encontrada.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(62,'lacuna','teia',NULL,NULL,'Delação premiada de Vorcaro homologada: não; PF e PGR rejeitaram três propostas (maio, junho e setembro de 2026).',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(63,'lacuna','teia',NULL,NULL,'Condenação criminal de Vorcaro: nenhuma encontrada; a única decisão sancionadora é a multa administrativa da CVM, com recurso possível.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(64,'lacuna','teia',NULL,NULL,'Instalação de CPI ou CPMI do Master: não confirmada em nenhuma fonte; em fevereiro/2026 estava parada.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(65,'lacuna','teia',NULL,NULL,'11ª fase da Compliance Zero: não encontrada até 09/10/2026.',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(66,'lacuna','teia',NULL,NULL,'Operação da PF contra Antônio Rueda ou ACM Neto: não confirmada; só há relato secundário (BPMoney, 10/09/2026) de que Vorcaro os citaria em proposta de delação, e eles negam.',8,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(67,'lacuna','teia',NULL,NULL,'Balanço do Master de 2025 e números de 2018 a 2020 (ativos, patrimônio, captação, lucro): não encontrados.',9,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(68,'lacuna','teia',NULL,NULL,'Resultado final do TCU sobre a atuação do BC: não encontrado.',10,NULL);
