INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(223,'aviso','dossie','meta.paginas',NULL,'[["Teia do Caso Master", "./teia.html"], ["Origens do Caso Master", "./origens.html"], ["Brasil ano a ano", "./brasil-ano-a-ano.html"]]',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(224,'aviso','pares','notas.pib_idh',NULL,'Dados do Banco Mundial (versao disponivel em out/2026): 2025 ja tem valor para todos os paises e indicadores; nenhum null nos indicadores 1 a 4. Valores sujeitos a revisao e podem ser estimativas preliminares para 2024-2025.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(225,'aviso','pares','notas.pib_idh',NULL,'IDH: a serie anual completa nao foi obtida (CSV completo do HDR e grande demais para o WebFetch; o filtro do OWID devolveu so extremos). Foram obtidos apenas anos-ancora: 1995, 2000, 2010, 2015, 2020, 2021, 2022, 2023 (HDR 2025). Demais anos = null; nada foi interpolado. 1990 (BRA .641, etc.) existe nos dados mas fica fora do recorte 1995-2025.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(226,'aviso','pares','notas.pib_idh',NULL,'IDH: ultimo ano publicado = 2023; 2024 e 2025 = null.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(227,'aviso','pares','notas.pib_idh',NULL,'Coluna Russia no Banco Mundial para PIB per capita e crescimento 1995-2025 vem com precisao diferente (ex.: 4.49999999920672), reflete a fonte.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(228,'aviso','pares','notas.pib_idh',NULL,'IDH da Turquia 2022 e 2023 ambos 0.853 conforme tabela HDR25.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(229,'aviso','pares','notas.pib_idh',NULL,'PIB nominal de ARG 1995-2001 reflete paridade 1 peso = 1 US$ da conversao do Banco Mundial; salto de 2001 para 2002 e efeito da desvalorizacao.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(230,'aviso','pares','notas.educacao',NULL,'Nenhum valor foi preenchido de memoria; ausencia = ano sem dado na fonte (chave omitida) ou null.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(231,'aviso','pares','notas.educacao',NULL,'alfabetizacao: serie esparsa. RUS so 2002, 2010, 2021; CHN so 2000, 2010, 2020; ARG so 2001 e 2020. IND 2023 (81.7) e 2024 (78.2) nao sao monotonicas com 2022 (76.3): oscilacao entre pesquisas. ZAF oscila (95.0 em 2019, 90.0 em 2021, 91.2 em 2024) por mudanca de pesquisa.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(232,'aviso','pares','notas.educacao',NULL,'anos_estudo: fonte e HDR 2025 via OWID, nao a planilha do hdr.undp.org (CSV grande truncado). Serie anual 1995-2023 para BRA, CHN, ARG, COL; para IND, RUS, MEX, IDN, TUR e ZAF so 1995, 2000, 2005, 2010, 2015, 2020 e 2023 (consulta por ano filtrado). Valores de 2021-2023 sao iguais entre si em BRA, CHN, ARG, COL (repetidos pela fonte, provavelmente sem dado novo).',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(233,'aviso','pares','notas.educacao',NULL,'anos_estudo: um outro dataset OWID ''average-years-of-schooling'' (Barro-Lee/outra base) deu valores bem diferentes (ex.: BRA 2020 = 8.0; COL 1995 = 6.68) e nao foi usado.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(234,'aviso','pares','notas.educacao',NULL,'gasto_educacao_pib: TUR 1998 vinha como 0 no Banco Mundial; descartado como dado invalido. TUR so tem 1995 e 2011-2022 (sem 1996-2010). IDN cai de 3.58 (2015) para 1.21 (2016) por quebra metodologica, nao queda real. CHN so 1995-1999 e 2023. Ultimo ano: ZAF 2024; ARG, CHN, IDN, RUS 2023; BRA, IND, MEX, TUR 2022; COL 2020.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(235,'aviso','pares','notas.educacao',NULL,'pisa: edicao 2025 nao incluida (resultados nao obtidos nas buscas; nao confirmado se ja saiu). Matematica 2000 e ciencias 2000/2003 nao constam na fonte OWID e ficaram null/ausentes. Russia: sem 2022 (nao participou/publicou). Turquia, Colombia e Indonesia: participacao a partir de 2003 (TUR), 2006 (COL); IDN desde 2000. Argentina: ausente em 2003; 2015 com ressalva de cobertura.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(236,'aviso','pares','notas.educacao',NULL,'pisa: Africa do Sul nunca participou do PISA (nao ha dados; mantido vazio). India so em 2009+ por dois estados, sem nota em leitura e ciencias.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(237,'aviso','pares','notas.educacao',NULL,'pisa: China nao tem dado nacional. Xangai 2012 (matematica 613, ciencias 580 e leitura 570) vem da Wikipedia, que tem inconsistencia de colunas; 2009 de Xangai nao foi obtido. 2022: B-S-J-Z participou mas resultados nao foram publicados (segundo Wikipedia).',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(238,'aviso','pares','notas.educacao',NULL,'Para comparacao informativa, Hong Kong e Macau (OWID) nao entram como ''China'' e foram omitidos.',8,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(239,'aviso','pares','notas.peso_economico',NULL,'Fonte: Banco Mundial, API v2 (NY.GDP.MKTP.CD, NE.EXP.GNFS.CD, NE.IMP.GNFS.CD, SP.POP.TOTL), consultada em 2026-10-09; lastupdated GDP 2026-07-13 (BRA/pais) e 2026-10-08 (CHN/WLD), populacao 2026-10-08.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(240,'aviso','pares','notas.peso_economico',NULL,'Unidades: US$ correntes; populacao em habitantes. WLD = total mundial do Banco Mundial (indicador do agregado, usado como denominador). Exportacoes e importacoes de bens e servicos (contas nacionais), nao comercio de mercadorias.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(241,'aviso','pares','notas.peso_economico',NULL,'Participacoes (%) = pais/WLD*100, 4 casas. Saldo = exportacoes - importacoes. Ranking 1 = maior PIB entre os 10 comparados.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(242,'aviso','pares','notas.peso_economico',NULL,'Importacoes de WLD nao foram coletadas (nao necessarias).',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(243,'aviso','pares','notas.peso_economico',NULL,'ranking_pib_brasil_mundo: null em todos os anos; nao foi coletada fonte confiavel do ranking mundial (nao estimado de memoria). Pode ser calculado com PIB de todos os paises da API (country/all) por ano.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(244,'aviso','pares','notas.peso_economico',NULL,'Valores de 2024/2025 podem ser preliminares/revistos pelo Banco Mundial. Dados ARG 2001 e anteriores sao a serie historica do WB (cambio oficial; quebra de serie em 2002 devido a desvalorizacao).',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(245,'aviso','pares','notas.peso_economico',NULL,'Valores transcritos da resposta da API via WebFetch (com resumidor); sem lacunas detectadas (31 anos x todos os paises).',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(246,'aviso','pares','notas.influencia_inovacao',NULL,'Series do Banco Mundial baixadas em 2026-10-08. Gasto militar cobre 1995-2025 completo; demais indicadores tem lacunas (null = sem dado na fonte; anos ausentes em gasto_pd_pib significam null).',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(247,'aviso','pares','notas.influencia_inovacao',NULL,'gasto_pd_pib: serie esparsa, so anos com valor. Brasil sem dado antes de 2000 e apos 2023; Colombia, Indonesia e India ate 2020; Indonesia tem so 2000, 2001, 2009, 2013 e 2016-2020; Africa do Sul tem lacunas (2002, 2000, 1998-1999 sem dado; 1997 e 2001 existem).',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(248,'aviso','pares','notas.influencia_inovacao',NULL,'patentes_residentes: 2025 null para todos; Indonesia 2012 null. Valores de outliers (ex.: ARG 2020/2016, COL 2022, IDN 2019) sao como publicados pela fonte, nao verificados.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(249,'aviso','pares','notas.influencia_inovacao',NULL,'artigos_cientificos: 1995 e 2024-2025 null para todos (fonte so cobre 1996-2023).',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(250,'aviso','pares','notas.influencia_inovacao',NULL,'gasto_militar_pib e usd: um unico fetch cobre os dez paises, sem nulos; fonte primaria SIPRI via Banco Mundial (nao consultado SIPRI diretamente). Valores de 2024-2025 podem ser revisados.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(251,'aviso','pares','notas.influencia_inovacao',NULL,'CSNU: mandatos de 2 anos, anos listados sao os anos de mandato. Extraido de pagina da Wikipedia (lista de membros do CSNU), nao do site un.org; o proprio extrator avisou que algumas tabelas eram dificeis de ler. Recomenda-se verificar em un.org/securitycouncil. Argentina: mandato 1994-1995, so 1995 entra na janela. Colombia tem mandato 2026-2027, fora da janela. China e Russia permanentes.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(252,'aviso','pares','notas.influencia_inovacao',NULL,'Foruns G20, BRICS, OCDE e nuclear: consultados via Wikipedia (G20, BRICS, OECD, List of states with nuclear weapons), nao nos sites oficiais; nao validado em g20.org, brics ou oecd.org. G20: Colombia nao e membro. Russia no BRICS/G20 sem alteracao. Turquia: parceira BRICS, nao membro pleno.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(253,'aviso','pares','notas.influencia_inovacao',NULL,'Nuclear: possuem China, India e Russia. Africa do Sul teve programa (6 armas, desmontado ~1989, aderiu ao TNP em 1991) mas nao possui hoje. Turquia nao possui, mas abriga armas dos EUA via compartilhamento nuclear da OTAN (estimativa ~20 em Incirlik, 2019).',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(254,'aviso','pares','notas.influencia_inovacao',NULL,'Brasil/OCDE: Key Partner e roteiro de acessao desde jun/2022; Argentina e Indonesia com roteiro desde mar/2024.',8,NULL);
