INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(1995,'bradesco',1566,'contexto',1,'Banco Bradesco now ranks first, with net profits of $815 million, up from $525 million in our previous ranking.','US$ 525 mi no ranking anterior da Euromoney (interpretado como FY1995). Ranking da Euromoney em US$ (critério e câmbio da revista): só corroboração de ordem de grandeza; o ranking usa o balanço em R$ pela legislação societária.');
