INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(1999,'eletropaulo',1615,'sustenta',0,'Mas, no mesmo período, o lucro caiu de R$ 404,4 milhões para R$ 238,9 milhões.','Novo; valor de 1999 como comparativo do balanço de 2000 (''caiu de R$ 404,4 milhões [99] para R$ 238,9 milhões [2000]'').');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(1999,'furnas',1616,'sustenta',0,'Furnas Centrais Elétricas informou ontem que a estatal obteve no ano passado lucro líquido de R$ 629 milhões, com aumento de 88,2% sobre os R$ 334 milhões do ano anterior.','Novo; valor de 1999 como comparativo do balanço de 2000.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(1999,'itau-unibanco',593,'contexto',2,NULL,'Fonte anterior do valor (1,955, conglomerado Itaúsa): outra base; mantida como contexto.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(1999,'itau-unibanco',1609,'sustenta',0,'De acordo com o balanço divulgado ontem, o banco paulista lucrou R$ 1,869 bilhão.','Substitui 1,955 (Itaúsa, outra base).');
