INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(1999,'petrobras',603,'sustenta',2,NULL,'Fonte anterior (Reuters/Gulf News: ''net profit'' de R$ 1,7 bi, arredondado); continua sustentando o valor.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(1999,'petrobras',1580,'sustenta',0,'A empresa fechou o ano com lucro líquido (depois de descontados os impostos) de R$ 1,771 bilhão','Valor exato em R$ (substitui o 1,7 arredondado da Reuters).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(1999,'petrobras',1584,'contexto',1,'Net income | $ 2,311 | $ 3,491 | $ 5,342 | $ 727 | $ 378','Net income US$ 727 mi em US GAAP (20-F FY2002). Outra base contábil (US GAAP, em US$; conversão a R$ do pesquisador com câmbio médio NÃO verificado): só corroboração; o ranking usa a legislação societária (BR GAAP).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(1999,'vale',1575,'contexto',0,'Net income ... US$ 574 US$ 319 US$ 698 US$ 412 US$ 1,086 US$ 901 US$ 585 (anos 1996 a 2000; 9M2000; 9M2001; ''in millions of US$'')','US$ 412 mi em US GAAP (F-3/A da CVRD). Outra base contábil (US GAAP, em US$; conversão a R$ do pesquisador com câmbio médio NÃO verificado): só corroboração; o ranking usa a legislação societária (BR GAAP).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(1999,'vale',1668,'sustenta',1,'A Vale registrou lucro de R$ 1,251 bilhão no ano passado, um resultado 21,6% superior ao de 98 (R$ 1,029 bilhão).','Confirma 1,251 (e 1998 = 1,029) em imprensa da época; a principal é monografia da PUC-Rio.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'banco-real',1617,'sustenta',0,'Esse resultado é 20,8% superior ao do ano passado, quando o grupo lucrou R$ 649,2 milhões.','Novo; valor de 2000 como comparativo do balanço de 2001 (banco Real + empresas ABN Amro no Brasil).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'bndes',1614,'sustenta',0,'O BNDES anunciou ontem que seu lucro em 2000 atingiu R$ 866,6 milhões','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'bradesco',609,'contexto',1,NULL,'Fonte anterior do valor (1,799, US GAAP no 20-F): outra base; mantida como contexto.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'bradesco',1671,'sustenta',0,'O Bradesco lucrou R$ 1,740 bilhões no ano passado. Esse resultado é 57,51% maior do que o de 1999, segundo balanço anual do banco divulgado ontem.','Substitui 1,799 (US GAAP).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'csn',614,'contexto',1,NULL,'Fonte anterior do valor (0,5, derivado de US$ 273 mi US GAAP): outra base; mantida como contexto.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'csn',1672,'sustenta',0,'o resultado ficou em R$ 296 milhões -81,5% menos do que o R$ 1,6 bilhão registrado em 2000. "Em 2000, a empresa teve um lucro não-recorrente e atípico.','Substitui 0,5 (derivado de US GAAP); valor de 2000 como comparativo do balanço de 2001.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'eletrobras',1628,'contexto',0,'a Eletrobrás teve lucro de R$ 1,1 bilhão em 2002, contra R$ 3,3 bilhões em 2001.','Só registro: 3,3/1,324 ≈ 2,49 para 2000; o 2,27 (mínimo) fica.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'furnas',1616,'sustenta',0,'Furnas Centrais Elétricas informou ontem que a estatal obteve no ano passado lucro líquido de R$ 629 milhões','Novo; números ''ainda pendentes de aprovação pela assembléia de acionistas''.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'petrobras',606,'contexto',2,NULL,'Fonte anterior do valor (9,8, derivado de US$ 5,342 bi US GAAP): outra base; mantida como contexto.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'petrobras',1669,'sustenta',0,'Os dados divulgados pela estatal referem-se apenas ao lucro dela própria, sem contar os números das subsidiárias. No geral, o lucro foi de R$ 9,942 bilhões (R$ 1,757 bilhão em 99).','Substitui 9,8 (derivado de US GAAP). Controladora: R$ 10,159 bi.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'petrobras',1670,'sustenta',1,'Em 2001, o lucro líquido consolidado -que inclui todas as empresas do grupo- da Petrobras e de suas subsidiárias foi de R$ 9,86 bilhões. Em 2000, fora de R$ 9,94 bilhões.','Confirma o consolidado de 2000 (9,94).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'telefonica-brasil',1618,'sustenta',0,'A Telefônica São Paulo (Telesp) lucrou R$ 1,576 bilhão no ano passado, 7,2% mais do que o R$ 1,470 bilhão obtido em 2000.','Novo; valor de 2000 como comparativo do balanço consolidado de 2001.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2000,'vale',1673,'sustenta',0,'A Companhia Vale do Rio Doce registrou no ano passado o maior lucro da sua história, totalizando R$ 2,133 bilhões, com crescimento de 70,5% sobre o resultado de 1999 (R$ 1,251 bilhão), o recorde anterior.','Confirma 2,133 em imprensa da época; a principal é monografia da PUC-Rio.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'banco-real',1617,'sustenta',0,'Com lucro líquido de R$ 784,3 milhões no ano passado, o banco Real e as empresas ABN Amro batem recorde histórico','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'bradesco',609,'contexto',1,NULL,'Fonte anterior do valor (2,27, US GAAP no 20-F): outra base; mantida como contexto.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'bradesco',1674,'sustenta',0,'O Bradesco obteve, no ano passado, lucro líquido de R$ 2,17 bilhões. O resultado é 24,7% maior do que o de 2000','Substitui 2,27 (US GAAP).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'caixa',1622,'sustenta',0,'A Caixa Econômica Federal, segundo maior banco do Brasil, fechou 2001 com prejuízo de R$ 4,687 bilhões.','Novo; a matéria antecipa o balanço (''Os números devem ser divulgados em duas semanas''); a Folha de 1/3/2003 confirma ''prejuízo de R$ 4,7 bi'' em 2001.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'cesp',1624,'sustenta',0,'A sangria na Cesp foi 320% mais alta que a registrada no ano passado, quando a empresa de geração de energia amargou perdas de R$ 813 milhões.','Novo; o ''ano passado'' da matéria é o ano anterior ao balanço de 2002, isto é 2001 (3,417/0,813 = +320%).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'csn',614,'contexto',2,NULL,'Fonte anterior do valor (1,24, derivado de US$ 527 mi US GAAP): outra base; mantida como contexto.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'csn',1633,'sustenta',1,'Em 2001 a empresa havia obtido lucro de R$ 296 milhões.','Confirma 0,296.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'csn',1672,'sustenta',0,'A CSN (Companhia Siderúrgica Nacional) lucrou menos em 2001: o resultado ficou em R$ 296 milhões','Substitui 1,24 (derivado de US GAAP).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'eletrobras',607,'contexto',1,NULL,'Fonte anterior do valor (3,0, mínimo da manchete ''supera os R$ 3 bilhões''): coerente; mantida como contexto.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'eletrobras',1628,'sustenta',0,'De acordo com o balanço divulgado ontem, a Eletrobrás teve lucro de R$ 1,1 bilhão em 2002, contra R$ 3,3 bilhões em 2001.','Substitui 3,0 (mínimo); valor arredondado.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'eletropaulo',1621,'sustenta',0,'A Eletropaulo teve um prejuízo líquido de R$ 871 milhões em 2002, conforme informações da ata da reunião do Conselho de Administração da companhia divulgada ontem. No ano anterior, a empresa havia obtido lucro de R$ 567 milhões.','Novo; valor de 2001 como comparativo de 2002.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'embraer',1619,'sustenta',0,'garantir um lucro recorde de R$ 1,1 bilhão no ano passado -70,5% superior ao de 2000.','Novo; valor arredondado.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'light',1623,'sustenta',0,'A Light -distribuidora de energia do Rio- fechou 2002 com um prejuízo de R$ 1,255 bilhão, o que representa um crescimento de 32% em relação ao resultado do ano anterior (R$ 951 milhões).','Novo; prejuízo de 2001 como comparativo de 2002 (1,255/0,951 = +32%).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'santander-brasil',1620,'sustenta',0,'O lucro líquido em 2001 atingiu R$ 1,089 bilhão, conforme balanço entregue ontem à Bolsa de Valores de São Paulo.','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'telefonica-brasil',1618,'sustenta',0,'A Telefônica São Paulo (Telesp) lucrou R$ 1,576 bilhão no ano passado, 7,2% mais do que o R$ 1,470 bilhão obtido em 2000. O balanço consolidado do grupo foi entregue ontem à CVM (Comissão de Valores Mobiliários).','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2001,'vale',1675,'sustenta',0,'Em 2001, o resultado atingiu R$ 3,051 bilhões -o maior da história da empresa e 43% superior aos R$ 2,133 bilhões de 2000.','Confirma 3,051 em imprensa da época (inclui R$ 1,702 bi da venda de participações em papel e celulose); a principal é monografia da PUC-Rio.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'banco-real',1626,'sustenta',0,'O ABN-Amro teve desempenho ainda melhor: lucro líquido de R$ 1,208 bilhão, 54% superior ao resultado alcançado em 2001.','Novo; 1,208/1,54 ≈ 0,784 confere com 2001 (Real + ABN Amro).');
