INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'caixa',1629,'sustenta',0,'A Caixa Econômica Federal recuperou parte do prejuízo recorde que teve em 2001 e encerrou o ano passado com um lucro de R$ 1,081 bilhão','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'cesp',1624,'sustenta',0,'A estatal registrou um prejuízo de R$ 3,417 bilhões em 2002, valor recorde em relação a todos os balanços daquele ano das companhias com ações em Bolsas divulgados até agora, de acordo com a consultoria Economática.','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'csn',1633,'sustenta',0,'A CSN (Companhia Siderúrgica Nacional) fechou o ano de 2002 com um prejuízo líquido de R$ 219 milhões no seu balanço','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'eletrobras',1628,'sustenta',0,'De acordo com o balanço divulgado ontem, a Eletrobrás teve lucro de R$ 1,1 bilhão em 2002, contra R$ 3,3 bilhões em 2001.','Novo; valor arredondado.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'eletropaulo',1621,'sustenta',0,'A Eletropaulo teve um prejuízo líquido de R$ 871 milhões em 2002, conforme informações da ata da reunião do Conselho de Administração da companhia divulgada ontem.','Novo; da ata do Conselho (balanço aprovado, ainda não divulgado oficialmente).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'embraer',1627,'sustenta',0,'Segundo o informe, a Embraer registrou em 2002 uma receita de R$ 7,7 bilhões. Já o lucro líquido foi de R$ 1,179 bilhão.','Novo; comunicado interno da empresa antecipado pela Folha (balanço oficial no dia seguinte).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'embratel',613,'sustenta',0,'Net income (loss) R$ 412 R$ 577 R$ (554) R$ (626) R$ 224  [colunas 1999-2003; 2002 = quarto valor]','Prejuízo confirmado no documento primário (BR GAAP). Dissertação da PUC-Rio (maxwell.vrac.puc-rio.br/4680/4680_5.PDF) traz R$ 627 mi (arredondamento).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'klabin',1634,'sustenta',0,'A Klabin Celulose e Papel, maior produtora de papel para embalagens do país, reverteu o prejuízo de R$ 208 milhões registrado em 2002 e lucrou R$ 1 bilhão no ano passado.','Novo; prejuízo de 2002 como comparativo de 2003.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'light',1623,'sustenta',0,'A Light -distribuidora de energia do Rio- fechou 2002 com um prejuízo de R$ 1,255 bilhão','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'santander-brasil',1625,'sustenta',0,'Na semana passada, o Banespa divulgou que teve lucro líquido de R$ 2,8 bilhões -158% maior que o registrado em 2001.','Novo; valor arredondado, citado na matéria sobre o Bradesco. 2,8/2,58 ≈ 1,09 confere com 2001.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'telefonica-brasil',1630,'sustenta',0,'A Telesp (operadora de telefonia fixa do grupo Telefônica em São Paulo) registrou queda de 31,7% no lucro em 2002 em relação ao ano anterior. A empresa obteve ganho de R$ 1,076 bilhão, ante R$ 1,576 bilhão em 2001.','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'telemar',612,'sustenta',0,'Net income (loss) 709,407 140,378 (415,598) 212,713 751,037  [colunas 2000-2004; 2002 = terceiro valor]','Confirmado no 20-F 2004 (SEC) e no 20-F 2003 do RI da TNL; o registrante é a holding TNL, não a operadora.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'telemar',1585,'contexto',1,'Lucro líquido do exercício 687.260 295.069  (R$ mil, 2002 e 2001)','Operadora Telemar Norte Leste S.A. (lucro de R$ 687 mi em 2002): entidade distinta da holding TNL; não entra no ranking (dupla contagem).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'telesp-celular-participacoes',1586,'sustenta',0,'producing a net loss of R$ 1,140.7 million in 2002 (US$ 322.2 million)','Press release de resultados de 2002 (6-K); o 20-F FY2003, já ligado, também traz (1,140.7).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'usiminas',1632,'sustenta',0,'A Usiminas lucrou R$ 1,3 bilhão em 2003, depois do prejuízo de R$ 321 milhões em 2002.','Novo; prejuízo de 2002 como comparativo de 2003 (sistema Usiminas, com a Cosipa).');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2002,'vale',1676,'sustenta',0,'A mineradora terminou o ano passado com lucro de R$ 4,509 bilhões, resultado 120,7% superior aos R$ 2,043 bilhões registrados em 2002.','Confirma 2,043 em imprensa (comparativo do balanço de 2003); a principal é tese da PUC-Rio.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2003,'bndes',1636,'sustenta',0,'permitiu ao BNDES (Banco Nacional de Desenvolvimento Econômico e Social) transformar em lucro de R$ 1,038 bilhão em 2003 um resultado que até o mês de novembro apontava prejuízo de R$ 2,125 bilhões.','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2003,'caixa',1635,'sustenta',0,'A Caixa Econômica Federal teve lucro recorde de R$ 1,616 bilhão no ano passado, com crescimento de 49,5% em relação ao ganho de 2002.','Novo; 1,616/1,495 ≈ 1,081 confere com 2002.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2003,'csn',614,'contexto',1,NULL,'Fonte anterior do valor (1,63, derivado de US$ 534 mi US GAAP): outra base; mantida como contexto.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2003,'csn',1640,'sustenta',0,'a CSN (Companhia Siderúrgica Nacional) lucrou R$ 1,982 bilhão em 2004, crescimento de 92,2% em relação ao resultado do ano anterior (R$ 1,031 bilhão).','Substitui 1,63 (derivado de US GAAP); valor de 2003 como comparativo de 2004.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2003,'eletrobras',1637,'sustenta',0,'A Eletrobrás teve lucro de R$ 323 milhões em 2003. Influenciado pelo queda do dólar, o resultado é 70% menor do que o do registrado em 2002 (R$ 1,1 bilhão).','Novo.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2003,'klabin',1634,'sustenta',0,'reverteu o prejuízo de R$ 208 milhões registrado em 2002 e lucrou R$ 1 bilhão no ano passado. O resultado foi reflexo da reestruturação financeira. A Klabin vendeu ativos para diminuir sua dívida líquida','Novo; valor arredondado (R$ 1 bilhão), com venda de ativos.');
INSERT INTO ranking_evidencia(ano, entidade_id, evidencia_id, papel, ordem, trecho_citado, nota) VALUES(2003,'usiminas',1632,'sustenta',0,'A Usiminas lucrou R$ 1,3 bilhão em 2003, depois do prejuízo de R$ 321 milhões em 2002.','Novo; valor arredondado (sistema Usiminas, com a Cosipa).');
