INSERT INTO entidade_valor(id, entidade_id, valor_brl, natureza, texto, quem_estima, data, principal, nota, qualidade, motivo_fraca, ordem, evidencia_id, trecho_citado) VALUES(2,'banco-master',83200000000.0,'passivo','R$ 83,2 bilhões em passivos exigíveis (IFData/BC, mar/2025)','Banco Central (IFData), via Agência Estado','2025-11-18',0,'Dado de março de 2025; R$ 62,2 bi em depósitos elegíveis ao FGC.','boa',NULL,1,1552,'o Master tinha R$ 86,4 bilhões em ativos, R$ 83,2 bilhões em passivos exigíveis e R$ 3,2 bilhões em patrimônio líquido.');
INSERT INTO entidade_valor(id, entidade_id, valor_brl, natureza, texto, quem_estima, data, principal, nota, qualidade, motivo_fraca, ordem, evidencia_id, trecho_citado) VALUES(3,'cpmi-do-inss',3300000000.0,'desviado','Valor desviado pode chegar a R$ 3,3 bilhões (relatório da maioria da CPMI, mar/2026)','Relatório da maioria da CPMI do INSS','2026-03',1,'Relatório de voto em separado, não aprovado pela comissão; PDF hospedado pelo PT. Data aproximada pela URL.','fraca','voto em separado (relatório da maioria) hospedado pelo PT, não o relatório aprovado pela comissão; data aproximada pela URL',0,490,'O valor total desviado poderá chegar a R$ 3,3 bilhões.');
INSERT INTO entidade_valor(id, entidade_id, valor_brl, natureza, texto, quem_estima, data, principal, nota, qualidade, motivo_fraca, ordem, evidencia_id, trecho_citado) VALUES(4,'daniel-vorcaro',5700000000.0,'bloqueado','Bloqueio e sequestro de R$ 5,7 bilhões em bens de 38 investigados, entre eles Vorcaro (jan/2026)','Ministro Dias Toffoli (STF), segundo o portal oficial do STF','2026-01-16',1,'Fonte trocada na rodada 13 (era agregador RSS, fraca). Atenção: R$ 5,7 bi é o total dos 38 investigados, não só de Vorcaro. Em jul/2026 Mendonça autorizou bloqueio de mais de R$ 2 bi em bens no exterior do Master (DGABC, 13/09/2026).','boa',NULL,0,1553,'o ministro determinou o bloqueio e sequestro de bens no valor total de R$ 5,7 bilhões, pertencentes a 38 investigados.');
INSERT INTO entidade_valor(id, entidade_id, valor_brl, natureza, texto, quem_estima, data, principal, nota, qualidade, motivo_fraca, ordem, evidencia_id, trecho_citado) VALUES(5,'operacao-carbono-oculto',52000000000.0,'movimentado','R$ 52 bilhões movimentados entre 2020 e 2024 (Receita Federal, ago/2025)','Receita Federal (nota de 28/8/2025, transcrita no Relatório ANP 1/2026)','2026-03-31',1,'Relatório nº 1/2026/SPC-CREG/SPC-e da ANP (31/3/2026, SEI 48610.223164/2025-18, pg. 20-22) transcreve a nota da Receita Federal de 28/8/2025 sobre a Carbono Oculto (nota 16; a página da Receita em gov.br passou a exigir login). Aberto pelo Chrome do usuário em 18/10/2026; PDF arquivado em data/raw/oficial/anp-relatorio-1-2026.pdf. Antes: Diario de Pernambuco/Estadão Conteúdo e CNN Brasil, que citavam o mesmo número.','boa',NULL,0,1554,'Entre 2020 e 2024, a movimentação financeira desses postos foi de R$ 52 bilhões, com recolhimento de tributos muito baixo e incompatível com suas atividades.');
INSERT INTO entidade_valor(id, entidade_id, valor_brl, natureza, texto, quem_estima, data, principal, nota, qualidade, motivo_fraca, ordem, evidencia_id, trecho_citado) VALUES(6,'operacao-carbono-oculto',8670000000.0,'sonegado','Mais de R$ 8,67 bilhões em créditos tributários federais constituídos pela Receita contra integrantes do esquema (ago/2025)','Receita Federal (nota de 28/8/2025, transcrita no Relatório ANP 1/2026)','2026-03-31',0,'Relatório nº 1/2026/SPC-CREG/SPC-e da ANP (31/3/2026, SEI 48610.223164/2025-18, pg. 20-22) transcreve a nota da Receita Federal de 28/8/2025 sobre a Carbono Oculto (nota 16; a página da Receita em gov.br passou a exigir login). Aberto pelo Chrome do usuário em 18/10/2026; PDF arquivado em data/raw/oficial/anp-relatorio-1-2026.pdf. Resolve a divergência CNN (R$ 7,6 bi ''sonegação'') × Estadão Conteúdo (R$ 8,6 bi): o número da Receita é R$ 8,67 bi em créditos tributários constituídos. Os postos foram autuados em mais de R$ 891 milhões; uma fintech do grupo movimentou mais de R$ 46 bilhões (2020-2024).','boa',NULL,1,1554,'A Receita Federal já constituiu créditos tributários federais de um total de mais de R$ 8,67 bilhões em pessoas e empresas integrantes do esquema.');
